function getDeviceFingerprint() {
  const ua = navigator.userAgent;
  if (/mobile/i.test(ua)) return "Mobile Phone (Web / PWA)";
  if (/tablet|ipad/i.test(ua)) return "Mobile Tablet (Web / PWA)";
  return "Desktop (Browser Session)";
}

