// 1. CUSTOMER DIRECTORY & 360° ANALYTICS ENGINE
function getCustomerBadgeHtml(docType = '') {
  const dt = (docType || '').trim().toUpperCase();
  const dtLower = (docType || '').trim().toLowerCase();

  if (dt === 'NIT') {
    return `<span class="badge badge-purple" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">NIT</span>`;
  }
  if (dt === 'NPE' || dt === 'NIT-E' || dtLower.includes('otro país') || dtLower.includes('exterior')) {
    return `<span class="badge badge-purple" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">NPE</span>`;
  }
  if (dt === 'DIE' || dtLower.includes('identificación extranjero')) {
    return `<span class="badge badge-amber" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">DIE</span>`;
  }
  if (dt === 'CE' || dtLower.includes('cédula de extranjería')) {
    return `<span class="badge badge-amber" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">CE</span>`;
  }
  if (dt === 'PAS' || dt === 'PP' || dtLower.includes('pasaporte')) {
    return `<span class="badge badge-blue" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">PP</span>`;
  }
  if (dt === 'TE' || dtLower.includes('tarjeta de extranjería')) {
    return `<span class="badge badge-amber" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">TE</span>`;
  }
  if (dt === 'TI' || dtLower.includes('tarjeta de identidad')) {
    return `<span class="badge badge-blue" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">TI</span>`;
  }
  if (dt === 'CC' || dtLower.includes('ciudadanía')) {
    return `<span class="badge badge-blue" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">CC</span>`;
  }
  return `<span class="badge badge-blue" style="font-size: 0.72rem; padding: 0.15rem 0.4rem;">${docType || 'CC'}</span>`;
}

function getCleanCustomerDocNumber(c) {
  let num = (c.rawDoc || c.documentNumber || '').trim();
  num = num.replace(/^(NIT|CC|CE|DIE|NPE|PAS|PP|TE|TI)\s*/i, '').trim();
  if (!num.includes('-') && c.verificationDigit && (c.documentType === 'NIT' || (c.documentType || '').toLowerCase().includes('otro país'))) {
    return `${num}-${c.verificationDigit}`;
  }
  return num || '-';
}

function renderCustomers() {
  const tableBody = document.getElementById("customersTableBody");
  const searchQuery = (document.getElementById("customerDirectorySearch")?.value || "").toLowerCase();
  const typeFilter = document.getElementById("customerTypeFilter")?.value || "ALL";

  if (!tableBody) return;

  const filtered = appState.customers.filter(c => {
    const abbr = (c.documentTypeAbbr || '').trim().toUpperCase();
    const dtUpper = (c.documentType || '').trim().toUpperCase();
    const dtLower = (c.documentType || '').trim().toLowerCase();
    let matchesType = true;

    if (typeFilter !== "ALL") {
      if (typeFilter === "NIT") {
        matchesType = (abbr === "NIT" || c.documentType === "NIT");
      } else if (typeFilter === "NPE" || typeFilter === "NIT-E") {
        matchesType = (abbr === "NPE" || dtUpper === 'NIT-E' || dtLower.includes('otro país') || dtLower.includes('exterior'));
      } else if (typeFilter === "CC") {
        matchesType = (abbr === "CC" || dtUpper === 'CC' || dtLower.includes('ciudadanía'));
      } else if (typeFilter === "DIE") {
        matchesType = (abbr === "DIE" || dtUpper === 'DIE' || dtLower.includes('identificación extranjero'));
      } else if (typeFilter === "CE") {
        matchesType = (abbr === "CE" || dtUpper === 'CE' || dtLower.includes('cédula de extranjería'));
      } else if (typeFilter === "PAS" || typeFilter === "PP") {
        matchesType = (abbr === "PAS" || abbr === "PP" || dtUpper === 'PAS' || dtUpper === 'PP' || dtLower.includes('pasaporte'));
      } else if (typeFilter === "TE") {
        matchesType = (abbr === "TE" || dtUpper === 'TE' || dtLower.includes('tarjeta de extranjería'));
      } else if (typeFilter === "TI") {
        matchesType = (abbr === "TI" || dtUpper === 'TI' || dtLower.includes('tarjeta de identidad'));
      }
    }

    const matchesSearch = c.name.toLowerCase().includes(searchQuery) ||
                          (c.documentNumber && c.documentNumber.includes(searchQuery)) ||
                          (c.rawDoc && c.rawDoc.includes(searchQuery)) ||
                          (c.city && c.city.toLowerCase().includes(searchQuery)) ||
                          (c.phone && c.phone.includes(searchQuery));
    return matchesType && matchesSearch;
  });

  // Update live dynamic counter badge bar for Customers
  const counterContainer = document.getElementById("customersCounterBadge");
  if (counterContainer) {
    const nitCount = filtered.filter(c => c.documentTypeAbbr === 'NIT' || c.documentType === 'NIT').length;
    const npeCount = filtered.filter(c => c.documentTypeAbbr === 'NPE' || (c.documentType || '').toLowerCase().includes('otro país')).length;
    const ccCount = filtered.filter(c => c.documentTypeAbbr === 'CC' || (c.documentType || '').toLowerCase().includes('ciudadanía')).length;
    const dieCount = filtered.filter(c => c.documentTypeAbbr === 'DIE' || (c.documentType || '').toLowerCase().includes('identificación extranjero')).length;
    const ceCount = filtered.filter(c => c.documentTypeAbbr === 'CE' || (c.documentType || '').toLowerCase().includes('cédula de extranjería')).length;
    const ppCount = filtered.filter(c => c.documentTypeAbbr === 'PP' || c.documentTypeAbbr === 'PAS' || (c.documentType || '').toLowerCase().includes('pasaporte')).length;
    const teCount = filtered.filter(c => c.documentTypeAbbr === 'TE' || (c.documentType || '').toLowerCase().includes('tarjeta de extranjería')).length;
    const tiCount = filtered.filter(c => c.documentTypeAbbr === 'TI' || (c.documentType || '').toLowerCase().includes('tarjeta de identidad')).length;

    counterContainer.innerHTML = `
      <span class="badge badge-purple" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">
        👥 Total: <strong>${filtered.length.toLocaleString('es-CO')}</strong> / ${appState.customers.length.toLocaleString('es-CO')}
      </span>
      <span class="badge badge-purple" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">
        🏢 NIT: <strong>${nitCount.toLocaleString('es-CO')}</strong>
      </span>
      <span class="badge badge-purple" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">
        🌎 NPE: <strong>${npeCount.toLocaleString('es-CO')}</strong>
      </span>
      <span class="badge badge-blue" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">
        👤 CC: <strong>${ccCount.toLocaleString('es-CO')}</strong>
      </span>
      <span class="badge badge-amber" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">
        ✈️ DIE: <strong>${dieCount.toLocaleString('es-CO')}</strong>
      </span>
      ${ceCount > 0 ? `<span class="badge badge-amber" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">🪪 CE: <strong>${ceCount.toLocaleString('es-CO')}</strong></span>` : ''}
      ${ppCount > 0 ? `<span class="badge badge-blue" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">📘 PP: <strong>${ppCount.toLocaleString('es-CO')}</strong></span>` : ''}
      ${teCount > 0 ? `<span class="badge badge-amber" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">📑 TE: <strong>${teCount.toLocaleString('es-CO')}</strong></span>` : ''}
      ${tiCount > 0 ? `<span class="badge badge-blue" style="font-size: 0.76rem; padding: 0.2rem 0.45rem;">🆔 TI: <strong>${tiCount.toLocaleString('es-CO')}</strong></span>` : ''}
    `;
  }

  tableBody.innerHTML = filtered.map(c => {
    const badgeHtml = getCustomerBadgeHtml(c.documentType);
    const cleanDocNum = getCleanCustomerDocNumber(c);

    // Calculate total purchases in COP for badge
    const totalPurchasedCOP = appState.movements
      .filter(m => (m.customerName && m.customerName.toLowerCase().includes(c.name.toLowerCase())) && m.type === 'SALIDA_VENTA')
      .reduce((sum, m) => {
        const prod = appState.products.find(p => p.id === m.productId);
        return sum + ((prod ? prod.salePrice : 100) * m.quantity);
      }, 0);

    return `
      <tr style="cursor: pointer;" onclick="selectCustomerFor360('${c.id}')" title="Clic para seleccionar perfil 360°">
        <td style="padding: 0.35rem 0.5rem; text-align: center;">${badgeHtml}</td>
        <td style="padding: 0.35rem 0.5rem; font-size: 0.8rem;"><strong style="font-family: monospace; color: var(--accent-green);">${cleanDocNum}</strong></td>
        <td style="padding: 0.35rem 0.5rem; font-size: 0.82rem;"><strong>${c.name}</strong></td>
        <td style="padding: 0.35rem 0.5rem; font-size: 0.78rem;">${c.city || 'Colombia'}</td>
        <td style="padding: 0.35rem 0.5rem; font-size: 0.78rem;">${c.phone || '-'}</td>
        <td style="padding: 0.35rem 0.5rem; font-size: 0.8rem;"><strong style="color: var(--accent-green);">$${totalPurchasedCOP.toLocaleString('es-CO')} COP</strong></td>
        <td style="padding: 0.35rem 0.5rem; text-align: center;">
          <div style="display: flex; gap: 0.25rem; justify-content: center;">
            <button class="btn btn-secondary" style="padding: 0.18rem 0.45rem; font-size: 0.72rem;" onclick="event.stopPropagation(); openCustomerModal('${c.id}')" title="Editar cliente/proveedor">
              ✏️ Editar
            </button>
            <button class="btn btn-primary" style="padding: 0.18rem 0.45rem; font-size: 0.72rem;" onclick="event.stopPropagation(); selectCustomerFor360('${c.id}')" title="Ver analítica 360°">
              📊 360°
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

function openCustomerModal(customerId = null) {
  const modal = document.getElementById("customerModal");
  const title = document.getElementById("customerModalTitle");
  const editIdInput = document.getElementById("customerEditId");
  const form = document.getElementById("customerForm");

  if (!modal) return;

  if (customerId) {
    const c = appState.customers.find(item => item.id === customerId);
    if (!c) return;

    if (title) title.textContent = `✏️ Editar Cliente / Proveedor (${c.name})`;
    if (editIdInput) editIdInput.value = c.id;

    const dtUpper = (c.documentType || '').trim().toUpperCase();
    const dt = (c.documentType || '').toLowerCase();
    let selType = "CC";
    if (dtUpper === "NIT" || dt === "nit") selType = "NIT";
    else if (dtUpper === "NPE" || dtUpper === "NIT-E" || dt.includes("otro país") || dt.includes("exterior")) selType = "NPE";
    else if (dtUpper === "DIE" || dt.includes("identificación extranjero")) selType = "DIE";
    else if (dtUpper === "CE" || dt.includes("cédula de extranjería")) selType = "CE";
    else if (dtUpper === "PP" || dtUpper === "PAS" || dt.includes("pasaporte")) selType = "PP";
    else if (dtUpper === "TE" || dt.includes("tarjeta de extranjería")) selType = "TE";
    else if (dtUpper === "TI" || dt.includes("tarjeta de identidad")) selType = "TI";
    else if (dtUpper === "CC" || dt.includes("ciudadanía")) selType = "CC";

    document.getElementById("customerModalDocType").value = selType;
    document.getElementById("customerModalDocNum").value = (c.documentNumber || c.rawDoc || '').replace(/^(NIT|CC|CE|DIE|NPE|PAS|PP|TE|TI)\s*/i, '').split('-')[0];
    document.getElementById("customerModalDV").value = c.verificationDigit || '';
    document.getElementById("customerModalName").value = c.name || '';
    document.getElementById("customerModalCity").value = c.city || '';
    document.getElementById("customerModalPhone").value = c.phone || '';
    document.getElementById("customerModalEmail").value = c.email || '';
    document.getElementById("customerModalAddress").value = c.address || '';
  } else {
    if (title) title.textContent = "👤 Crear Nuevo Cliente / Proveedor";
    if (editIdInput) editIdInput.value = "";
    if (form) form.reset();
  }

  toggleCustomerDVField();
  modal.classList.add("active");
}

function closeCustomerModal() {
  const modal = document.getElementById("customerModal");
  if (modal) modal.classList.remove("active");
}

function toggleCustomerDVField() {
  const docType = document.getElementById("customerModalDocType")?.value;
  const dvInput = document.getElementById("customerModalDV");
  if (dvInput) {
    if (docType === "NIT" || docType === "NPE") {
      dvInput.style.display = "block";
      dvInput.removeAttribute("disabled");
    } else {
      dvInput.style.display = "none";
      dvInput.value = "";
    }
  }
}

function handleSaveCustomer(event) {
  event.preventDefault();
  const editId = document.getElementById("customerEditId")?.value;
  const docTypeVal = document.getElementById("customerModalDocType")?.value;
  const docNumVal = document.getElementById("customerModalDocNum")?.value.trim();
  const dvVal = document.getElementById("customerModalDV")?.value.trim();
  const nameVal = document.getElementById("customerModalName")?.value.trim();
  const cityVal = document.getElementById("customerModalCity")?.value.trim();
  const phoneVal = document.getElementById("customerModalPhone")?.value.trim();
  const emailVal = document.getElementById("customerModalEmail")?.value.trim();
  const addressVal = document.getElementById("customerModalAddress")?.value.trim();

  if (!docNumVal || !nameVal) {
    alert("⚠️ Por favor ingrese el número de documento y la razón social/nombre.");
    return;
  }

  const docTypeMap = {
    "CC": "Cédula de ciudadanía",
    "CE": "Cédula de extranjería",
    "DIE": "Documento de identificación extranjero",
    "NIT": "NIT",
    "NPE": "Nit de otro país / Sin identificación del exterior (43 medios magnéticos)",
    "PP": "Pasaporte",
    "TE": "Tarjeta de extranjería",
    "TI": "Tarjeta de identidad"
  };

  const docTypeFull = docTypeMap[docTypeVal] || docTypeVal;
  const rawFormattedDoc = (docTypeVal === "NIT" || docTypeVal === "NPE") && dvVal ? `${docNumVal}-${dvVal}` : docNumVal;

  if (editId) {
    const custIndex = appState.customers.findIndex(c => c.id === editId);
    if (custIndex !== -1) {
      appState.customers[custIndex] = {
        ...appState.customers[custIndex],
        documentType: docTypeFull,
        documentNumber: docNumVal,
        verificationDigit: dvVal || null,
        rawDoc: rawFormattedDoc,
        name: nameVal,
        city: cityVal,
        phone: phoneVal,
        email: emailVal,
        address: addressVal
      };
      addActivityLog("EDICION", "CustomerDirectory", `Cliente/Proveedor '${nameVal}' (${rawFormattedDoc}) actualizado.`);
    }
  } else {
    const newCust = {
      id: "cust-" + Date.now(),
      documentType: docTypeFull,
      documentNumber: docNumVal,
      verificationDigit: dvVal || null,
      rawDoc: rawFormattedDoc,
      name: nameVal,
      city: cityVal,
      phone: phoneVal,
      email: emailVal,
      address: addressVal
    };
    appState.customers.unshift(newCust);
    addActivityLog("CREACION", "CustomerDirectory", `Nuevo Cliente/Proveedor '${nameVal}' (${rawFormattedDoc}) registrado.`);
  }

  closeCustomerModal();
  renderCustomers();
  populateCustomerDropdowns();
}

function populateCustomerDropdowns() {
  if (typeof populateSelects === 'function') {
    populateSelects();
  }
}

function selectCustomerFor360(customerId) {
  appState.selectedCustomerId = customerId;
  const customer = appState.customers.find(c => c.id === customerId);
  if (customer) {
    addActivityLog("CONSULTA", "Customer360Profile", `Inspección de perfil 360° y estadísticas del cliente '${customer.name}'.`);
  }
  renderCustomer360Analytics();
  switchView('view-customers-analytics');
}

function renderCustomer360Analytics() {
  const customerId = appState.selectedCustomerId || (appState.customers[0] ? appState.customers[0].id : null);
  if (!customerId) return;

  const customer = appState.customers.find(c => c.id === customerId);
  if (!customer) return;

  // Header info
  const formattedDoc = customer.documentType === 'NIT' ? `NIT ${customer.documentNumber}-${customer.verificationDigit || '0'}` : `CC ${customer.documentNumber}`;
  
  document.getElementById("cust360Name").textContent = customer.name;
  document.getElementById("cust360Doc").textContent = `${customer.documentType}: ${formattedDoc}`;
  document.getElementById("cust360City").textContent = customer.city || "Colombia";
  document.getElementById("cust360Phone").textContent = customer.phone || "No Registrado";
  document.getElementById("cust360Email").textContent = customer.email || "No Registrado";

  // Customer movements
  const customerMovements = appState.movements.filter(m => 
    m.type === 'SALIDA_VENTA' && m.customerName && m.customerName.toLowerCase().includes(customer.name.toLowerCase())
  );

  // Financial Metrics
  let totalSpentCOP = 0;
  let totalUnits = 0;

  customerMovements.forEach(m => {
    const prod = appState.products.find(p => p.id === m.productId);
    const unitPrice = prod ? prod.salePrice : 100;
    totalSpentCOP += (unitPrice * m.quantity);
    totalUnits += m.quantity;
  });

  const purchaseCount = customerMovements.length;
  const avgPurchaseTicket = purchaseCount > 0 ? (totalSpentCOP / purchaseCount) : 0;
  const avgUnitsPerSemester = (totalUnits * 0.5).toFixed(1);

  document.getElementById("cust360TotalSpent").textContent = `$${totalSpentCOP.toLocaleString('es-CO')} COP`;
  document.getElementById("cust360TotalUnits").textContent = `${totalUnits} Unidades`;
  document.getElementById("cust360AvgTicket").textContent = `$${avgPurchaseTicket.toFixed(2)} COP`;
  document.getElementById("cust360SemesterFreq").textContent = `${avgUnitsPerSemester} Unds / Semestre`;

  // Purchased Products & Serials Breakdown Table
  const tableBody = document.getElementById("cust360PurchasedProductsTable");
  if (tableBody) {
    if (customerMovements.length === 0) {
      tableBody.innerHTML = `<tr><td colspan="6" style="text-align: center; color: var(--text-muted); padding: 1rem;">No se registran compras previas para este cliente.</td></tr>`;
    } else {
      tableBody.innerHTML = customerMovements.map(m => {
        const prod = appState.products.find(p => p.id === m.productId);
        const unitPrice = prod ? prod.salePrice : 100;
        const subtotal = unitPrice * m.quantity;

        // Find serialized item assigned to this customer for this sale/invoice
        const serialItems = appState.serializedItems.filter(i => 
          i.currentCustomerId === customer.id || (i.invoiceNumber && i.invoiceNumber === m.invoiceNumber)
        );

        return `
          <tr>
            <td><strong>${m.date}</strong></td>
            <td><strong>${prod ? prod.sku : ''}</strong> - ${prod ? prod.name : 'Insumo'}</td>
            <td><span class="badge badge-purple">${prod ? prod.category : 'General'}</span></td>
            <td><strong>${m.quantity}</strong></td>
            <td>$${subtotal.toLocaleString('es-CO')} COP</td>
            <td>
              ${prod && prod.requiresSerial ? `
                ${serialItems.length > 0 ? serialItems.map(s => `
                  <span style="background: rgba(16,185,129,0.15); border: 1px solid rgba(16,185,129,0.3); padding: 0.15rem 0.4rem; border-radius: 4px; font-family: monospace; color: var(--accent-green); font-size: 0.8rem;">
                    SN: ${s.serialNumber}
                  </span>
                `).join(' ') : '<span style="color: var(--accent-amber); font-size: 0.8rem;">Serializado sin asignar</span>'}
              ` : '<span style="color: var(--text-muted); font-size: 0.8rem;">Consumible (Sin Serial)</span>'}
            </td>
          </tr>
        `;
      }).join('');
    }
  }

  // Active Reservations for this Customer
  const custReservations = appState.reservations.filter(r => r.customerId === customer.id);
  const reservationsContainer = document.getElementById("cust360ReservationsContainer");
  if (reservationsContainer) {
    if (custReservations.length === 0) {
      reservationsContainer.innerHTML = `<div style="color: var(--text-muted); font-size: 0.85rem;">No hay bloqueos ni reservas activas para este cliente.</div>`;
    } else {
      reservationsContainer.innerHTML = custReservations.map(r => {
        const prod = appState.products.find(p => p.id === r.productId);
        return `
          <div style="background: rgba(245, 158, 11, 0.1); border: 1px solid rgba(245, 158, 11, 0.3); padding: 0.75rem 1rem; border-radius: var(--radius-md); margin-bottom: 0.5rem; display: flex; justify-content: space-between; align-items: center;">
            <div>
              <strong style="color: #fcd34d;">🔒 RESERVA ACTIVA: ${prod ? prod.sku : ''} - ${prod ? prod.name : ''}</strong>
              <div style="font-size: 0.8rem; color: var(--text-muted); margin-top: 0.2rem;">
                Cantidad Bloqueada: <strong>${r.quantity} unidades</strong> | Motivo: ${r.reason}
              </div>
            </div>
            <span class="badge badge-amber">${r.status}</span>
          </div>
        `;
      }).join('');
    }
  }

  // Warranties & Returns for this Customer
  const custSerials = appState.serializedItems.filter(i => i.currentCustomerId === customer.id);
  const warrantyContainer = document.getElementById("cust360WarrantiesContainer");
  if (warrantyContainer) {
    if (custSerials.length === 0) {
      warrantyContainer.innerHTML = `<div style="color: var(--text-muted); font-size: 0.85rem;">Este cliente no posee equipos serializados bajo garantía registrada.</div>`;
    } else {
      warrantyContainer.innerHTML = custSerials.map(s => {
        const prod = appState.products.find(p => p.id === s.productId);
        const warrantyMonths = prod ? (prod.warrantyMonths || 12) : 12;
        const saleDateObj = s.saleDate ? new Date(s.saleDate) : new Date(s.entryDate);
        const expiryDateObj = new Date(saleDateObj);
        expiryDateObj.setMonth(expiryDateObj.getMonth() + warrantyMonths);

        const today = new Date();
        const isValid = (today <= expiryDateObj);
        const daysLeft = Math.max(0, Math.round((expiryDateObj - today) / (1000 * 60 * 60 * 24)));

        return `
          <div style="background: rgba(15, 23, 42, 0.8); border: 1px solid var(--border-color); padding: 0.75rem 1rem; border-radius: var(--radius-md); margin-bottom: 0.5rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 0.5rem;">
            <div>
              <strong style="color: var(--text-main);">${prod ? prod.name : 'Equipo'}</strong>
              <div style="font-size: 0.8rem; color: var(--text-muted); margin-top: 0.2rem;">
                Serial: <strong style="color: var(--accent-green); font-family: monospace;">${s.serialNumber}</strong> | Factura: ${s.invoiceNumber || 'N/A'}
              </div>
            </div>
            <div>
              <span class="badge ${isValid ? 'badge-green' : 'badge-red'}">
                ${isValid ? `🛡️ Garantía Vigente (${daysLeft} días)` : '❌ Expirada'}
              </span>
            </div>
          </div>
        `;
      }).join('');
    }
  }
}

function handleWarrantySerialInput(event) {
  const query = event.target.value.trim().toLowerCase();
  const suggBox = document.getElementById("warrantySerialSuggestions");

  if (!suggBox) return;

  if (query.length === 0) {
    suggBox.classList.remove("active");
    suggBox.innerHTML = "";
    return;
  }

  ensureGlobalSerials();

  const matchingItems = appState.serializedItems.filter(item => {
    const prod = appState.products.find(p => p.id === item.productId);
    const matchesSerial = item.serialNumber.toLowerCase().includes(query);
    const matchesSku = prod ? prod.sku.toLowerCase().includes(query) : false;
    const matchesName = prod ? prod.name.toLowerCase().includes(query) : false;
    return matchesSerial || matchesSku || matchesName;
  });

  if (matchingItems.length === 0) {
    suggBox.innerHTML = `
      <div style="padding: 0.75rem 1rem; color: var(--text-muted); font-size: 0.85rem;">
        ❌ No se encontraron seriales que coincidan con "<strong>${query}</strong>"
      </div>
    `;
    suggBox.classList.add("active");
    return;
  }

  suggBox.innerHTML = matchingItems.map(item => {
    const prod = appState.products.find(p => p.id === item.productId);
    const customer = appState.customers.find(c => c.id === item.currentCustomerId);
    return `
      <div class="suggestion-item" onclick="selectSerialSuggestion('${item.serialNumber}')">
        <div>
          <strong style="color: var(--accent-green); font-family: monospace; font-size: 0.95rem;">${item.serialNumber}</strong>
          <div style="font-size: 0.8rem; color: var(--text-main); font-weight: 500;">${prod ? prod.sku : ''} - ${prod ? prod.name : 'Equipo'}</div>
          <div style="font-size: 0.73rem; color: var(--text-muted);">
            Status: ${item.status} | Cliente: ${customer ? customer.name : 'Bodega'}
          </div>
        </div>
        <span class="badge ${item.status === 'EN_STOCK' ? 'badge-green' : 'badge-amber'}">${item.status}</span>
      </div>
    `;
  }).join('');

  suggBox.classList.add("active");
}

function selectSerialSuggestion(serialNumber) {
  const input = document.getElementById("warrantySerialInput");
  const suggBox = document.getElementById("warrantySerialSuggestions");

  if (input) input.value = serialNumber;
  if (suggBox) suggBox.classList.remove("active");

  lookupWarrantyBySerial(serialNumber);
}

function openCameraForWarranty() {
  openCameraModal();
}

function renderAuditLogView() {
  const tableBody = document.getElementById("auditLogTableBody");
  const dashboardAuditBox = document.getElementById("auditLogBox");

  if (!tableBody) return;

  const actionFilter = document.getElementById("auditActionFilter")?.value || "ALL";
  const userFilter = document.getElementById("auditUserFilter")?.value || "ALL";
  const searchQuery = (document.getElementById("auditSearch")?.value || "").toLowerCase();

  // SUPERUSER PRIVACY ISOLATION IN AUDIT LOGS:
  // Nobody except gerencia@softproductiva.com can see logs relating to gerencia@softproductiva.com!
  const isSuperuserActive = (appState.currentUser.email === 'gerencia@softproductiva.com');

  const visibleLogs = appState.auditLogs.filter(log => {
    const isSuperuserLog = (log.userEmail === 'gerencia@softproductiva.com' || (log.description && log.description.includes('gerencia@softproductiva.com')));
    if (isSuperuserLog && !isSuperuserActive) {
      return false; // Hide completely from audit logs
    }

    const matchesAction = (actionFilter === "ALL" || log.actionType === actionFilter);
    const matchesUser = (userFilter === "ALL" || log.userName === userFilter || log.userEmail === userFilter);
    const matchesQuery = log.description.toLowerCase().includes(searchQuery) || log.ipAddress.includes(searchQuery) || log.userName.toLowerCase().includes(searchQuery);
    return matchesAction && matchesUser && matchesQuery;
  });

  tableBody.innerHTML = visibleLogs.map(l => {
    let actionBadgeClass = "badge-blue";
    if (l.actionType === "LOGIN") actionBadgeClass = "badge-purple";
    if (l.actionType === "IMPORTACION") actionBadgeClass = "badge-green";
    if (l.actionType === "EXPORTACION") actionBadgeClass = "badge-amber";
    if (l.actionType === "GARANTIA") actionBadgeClass = "badge-red";

    const parts = (l.timestamp || '').split(' ');
    const dateStr = parts[0] || l.timestamp;
    const timeStr = parts[1] || '';

    return `
      <tr>
        <td style="white-space: nowrap; min-width: 110px;">
          <div style="font-weight: 700; color: var(--text-main); font-family: monospace; font-size: 0.88rem; line-height: 1.2;">${dateStr}</div>
          ${timeStr ? `<div style="font-size: 0.8rem; color: var(--text-muted); font-family: monospace; line-height: 1.2; margin-top: 0.15rem;">${timeStr}</div>` : ''}
        </td>
        <td>
          <div style="font-weight: 600;">${l.userName}</div>
          <div style="font-size: 0.73rem; color: var(--text-muted);">${l.userEmail} (${l.roleName})</div>
        </td>
        <td><span class="badge ${actionBadgeClass}">${l.actionType}</span></td>
        <td>
          <div>${l.description}</div>
          <div style="font-size: 0.72rem; color: var(--accent-green); margin-top: 0.2rem;">Entidad: ${l.entityName}</div>
        </td>
        <td><strong style="font-family: monospace; font-size: 0.85rem; color: var(--accent-teal);">${l.ipAddress}</strong></td>
        <td><div style="font-size: 0.78rem; color: var(--text-muted);">${l.deviceType}</div></td>
      </tr>
    `;
  }).join('');

  if (dashboardAuditBox) {
    const dashboardLogs = appState.auditLogs.filter(log => {
      const isSuperuserLog = (log.userEmail === 'gerencia@softproductiva.com' || (log.description && log.description.includes('gerencia@softproductiva.com')));
      if (isSuperuserLog && !isSuperuserActive) return false;
      return true;
    });

    dashboardAuditBox.innerHTML = dashboardLogs.slice(0, 8).map(l => 
      `<div>[${l.timestamp}] [${l.actionType}] [IP: ${l.ipAddress}] ${l.userName}: ${l.description}</div>`
    ).join('');
  }
}

function exportAuditLogsCSV() {
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo el Administrador puede exportar el log de auditoría.");
    return;
  }

  const isSuperuserActive = (appState.currentUser.email === 'gerencia@softproductiva.com');
  const exportableLogs = appState.auditLogs.filter(log => {
    const isSuperuserLog = (log.userEmail === 'gerencia@softproductiva.com' || (log.description && log.description.includes('gerencia@softproductiva.com')));
    if (isSuperuserLog && !isSuperuserActive) return false;
    return true;
  });

  let csv = "FechaHora;Usuario;Email;Rol;TipoAccion;Entidad;Descripcion;IPAddress;Dispositivo\n";
  exportableLogs.forEach(l => {
    csv += `"${l.timestamp}";"${l.userName}";"${l.userEmail}";"${l.roleName}";"${l.actionType}";"${l.entityName}";"${l.description}";"${l.ipAddress}";"${l.deviceType}"\n`;
  });

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.setAttribute("download", `Log_Auditoria_Forense_MasCampo_${new Date().toISOString().substring(0,10)}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  addActivityLog("EXPORTACION", "AuditLog", "Exportación completa de Log de Auditoría en CSV.");
}

