function handleTransferProductSelect() {
  const prodId = document.getElementById("transferProduct")?.value;
  const fromLocId = document.getElementById("transferFromLoc")?.value;
  const availableHelp = document.getElementById("transferStockAvailableHelp");
  const serialGroup = document.getElementById("transferSerialGroup");
  const serialList = document.getElementById("transferSerialList");

  if (!prodId || !fromLocId) return;

  const product = appState.products.find(p => p.id === prodId);
  if (!product) return;

  ensureProductLocations();

  const stockAtOrigin = (product.stockByLocation && product.stockByLocation[fromLocId]) ? product.stockByLocation[fromLocId] : 0;
  
  const fromLocObj = appState.locations.find(l => l.id === fromLocId);
  if (availableHelp) {
    availableHelp.textContent = `📍 Stock Disponible en '${fromLocObj ? fromLocObj.name : 'Origen'}': ${stockAtOrigin} ${product.unitOfMeasure}`;
  }

  if (product.requiresSerial) {
    ensureAllSerialsForProduct(product);
    const originSerials = appState.serializedItems.filter(i => i.productId === prodId && i.status === 'EN_STOCK' && i.currentLocationId === fromLocId);
    
    if (serialGroup) serialGroup.style.display = "block";
    if (serialList) {
      if (originSerials.length === 0) {
        serialList.innerHTML = `<div style="color: var(--accent-amber); font-size: 0.8rem;">No hay seriales individuales disponibles en la sede de origen seleccionada.</div>`;
      } else {
        serialList.innerHTML = originSerials.map(s => `
          <label style="display: flex; align-items: center; gap: 0.3rem; background: rgba(16,185,129,0.15); border: 1px solid rgba(16,185,129,0.3); padding: 0.25rem 0.5rem; border-radius: 4px; font-family: monospace; font-size: 0.8rem; cursor: pointer;">
            <input type="checkbox" class="transfer-serial-checkbox" value="${s.serialNumber}">
            <span>${s.serialNumber}</span>
          </label>
        `).join('');
      }
    }
  } else {
    if (serialGroup) serialGroup.style.display = "none";
  }
}

function handleTransferStock(e) {
  e.preventDefault();
  const prodId = document.getElementById("transferProduct").value;
  const fromLocId = document.getElementById("transferFromLoc").value;
  const toLocId = document.getElementById("transferToLoc").value;
  const qty = parseInt(document.getElementById("transferQuantity").value);
  const notes = document.getElementById("transferNotes").value.trim();

  if (fromLocId === toLocId) {
    alert("⚠️ ERROR: La ubicación de origen y destino deben ser distintas.");
    return;
  }

  const product = appState.products.find(p => p.id === prodId);
  const fromLoc = appState.locations.find(l => l.id === fromLocId);
  const toLoc = appState.locations.find(l => l.id === toLocId);

  if (!product || !fromLoc || !toLoc) return;

  ensureProductLocations();
  const currentOriginStock = product.stockByLocation[fromLocId] || 0;

  if (qty > currentOriginStock) {
    alert(`⚠️ STOCK INSUFICIENTE EN ORIGEN: Solo hay ${currentOriginStock} unidades disponibles en '${fromLoc.name}'.`);
    return;
  }

  let selectedSerialNumbers = [];
  if (product.requiresSerial) {
    const checkedBoxes = document.querySelectorAll(".transfer-serial-checkbox:checked");
    checkedBoxes.forEach(box => selectedSerialNumbers.push(box.value));

    if (selectedSerialNumbers.length !== qty) {
      alert(`⚠️ ERROR DE SERIALES: Ha indicado trasladar ${qty} unidades, pero ha seleccionado ${selectedSerialNumbers.length} números de serie. La cantidad debe coincidir exactamente con los seriales seleccionados.`);
      return;
    }
  }

  product.stockByLocation[fromLocId] -= qty;
  product.stockByLocation[toLocId] = (product.stockByLocation[toLocId] || 0) + qty;

  if (product.requiresSerial && selectedSerialNumbers.length > 0) {
    selectedSerialNumbers.forEach(sNum => {
      const serialObj = appState.serializedItems.find(i => i.serialNumber === sNum && i.productId === prodId);
      if (serialObj) {
        serialObj.currentLocationId = toLocId;
        serialObj.history.push({
          type: "TRASLADO_UBICACION",
          date: new Date().toISOString().substring(0, 10),
          user: appState.currentUser.name,
          description: `Traslado de '${fromLoc.name}' a '${toLoc.name}'. Guía/Notas: ${notes || 'Sin observaciones'}`
        });
      }
    });
  }

  const transferMov = {
    id: `mov-tr-${Date.now()}`,
    date: new Date().toISOString().substring(0, 10),
    type: "TRASLADO_UBICACION",
    productId: prodId,
    quantity: qty,
    invoiceNumber: notes || `REM-TR-${Date.now().toString().slice(-4)}`,
    customerName: `Traslado: ${fromLoc.name} ➔ ${toLoc.name}`,
    user: appState.currentUser.name,
    notes: `Traslado de ${qty} unidades de '${fromLoc.name}' a '${toLoc.name}'. Seriales: ${selectedSerialNumbers.join(', ') || 'N/A'}`
  };

  appState.movements.unshift(transferMov);
  addActivityLog("MODIFICACION", "StockTransfer", `Traslado de ${qty} unidades de '${product.sku}' desde '${fromLoc.name}' hacia '${toLoc.name}'.`);

  alert(`✅ TRASLADO EXITOSO: ${qty} unidades de ${product.sku} trasladadas a '${toLoc.name}'.`);
  document.getElementById("transferStockForm").reset();
  handleTransferProductSelect();
  populateDropdowns();
  renderAllViews();
}

// AUTOMATED SIGO SALES REPORT INGESTION ENGINE WITH ANTI-DUPLICATION VALIDATION
function triggerSigoReportImport() {
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo el Administrador está autorizado para procesar y cargar reportes de Sigo.");
    return;
  }
  document.getElementById("sigoReportFileInput").click();
}

function handleSigoReportUpload(event) {
  const file = event.target.files[0];
  if (!file) return;

  processAutomatedSigoReport(file.name);
}

function processAutomatedSigoReport(fileName) {
  const simulatedSigoBatch = [
    {
      invoiceNumber: "FACT-SIGO-2026-901",
      date: new Date().toISOString().substring(0, 10),
      customerNit: "901.888.777-2",
      customerName: "AGROVET DEL LLANO S.A.S (Cliente Nuevo Sigo)",
      customerPhone: "+57 318 999 4455",
      customerEmail: "compras@agrovetllano.co",
      items: [
        { sku: "MC 001", quantity: 20 },
        { sku: "MC 004", quantity: 15 }
      ]
    },
    {
      invoiceNumber: "FACT-SIGO-2026-902",
      date: new Date().toISOString().substring(0, 10),
      customerNit: "900.138.371-1",
      customerName: "FINCA DON PEDRO PMO S.A.S",
      customerPhone: "+57 310 456 7890",
      customerEmail: "donpedro@finca.co",
      items: [
        { sku: "MC 003", quantity: 1 }
      ]
    }
  ];

  let newCustomersCreated = 0;
  let totalExitsRegistered = 0;
  let newInvoicesCount = 0;
  let duplicateInvoicesCount = 0;
  const skippedInvoices = [];

  simulatedSigoBatch.forEach(invoiceData => {
    const isAlreadyProcessed = appState.movements.some(m => m.invoiceNumber === invoiceData.invoiceNumber);

    if (isAlreadyProcessed) {
      duplicateInvoicesCount++;
      skippedInvoices.push(invoiceData.invoiceNumber);
      return;
    }

    newInvoicesCount++;

    let customer = appState.customers.find(c => c.documentNumber === sanitizeDocument(invoiceData.customerNit).cleanDoc || c.name.toLowerCase() === invoiceData.customerName.toLowerCase());
    
    if (!customer) {
      const parsedDoc = sanitizeDocument(invoiceData.customerNit);
      customer = {
        id: `cust-${Date.now()}-${Math.floor(Math.random()*100)}`,
        documentType: parsedDoc.docType,
        documentNumber: parsedDoc.cleanDoc,
        verificationDigit: parsedDoc.dv,
        name: invoiceData.customerName,
        phone: invoiceData.customerPhone,
        email: invoiceData.customerEmail,
        city: "Registrado Automáticamente vía Sigo Report",
        address: "Cierre de Caja Sigo"
      };
      appState.customers.push(customer);
      newCustomersCreated++;
      addActivityLog("CREACION", "CustomerAutoIngest", `Auto-creación de cliente nuevo '${customer.name}' desde reporte Sigo.`);
    }

    invoiceData.items.forEach(itemInfo => {
      const product = appState.products.find(p => p.sku === itemInfo.sku);
      if (product) {
        product.physicalStock = Math.max(0, product.physicalStock - itemInfo.quantity);
        totalExitsRegistered += itemInfo.quantity;

        const newMov = {
          id: `mov-sigo-${Date.now()}-${Math.floor(Math.random()*1000)}`,
          date: invoiceData.date,
          type: "SALIDA_VENTA",
          productId: product.id,
          quantity: itemInfo.quantity,
          invoiceNumber: invoiceData.invoiceNumber,
          customerName: customer.name,
          user: `${appState.currentUser.name} (Auto-Sigo)`,
          notes: `Salida registrada automáticamente por cierre de ventas de Sigo (Archivo: ${fileName})`,
          attachments: [
            { name: fileName, type: 'excel', icon: '📊' }
          ]
        };

        appState.movements.unshift(newMov);

        if (product.requiresSerial) {
          let serialItem = appState.serializedItems.find(i => i.productId === product.id && i.status === 'EN_STOCK');
          if (serialItem) {
            serialItem.status = "VENDIDO";
            serialItem.currentCustomerId = customer.id;
            serialItem.saleDate = invoiceData.date;
            serialItem.invoiceNumber = invoiceData.invoiceNumber;
            serialItem.attachments = [...(serialItem.attachments || []), { name: fileName, type: 'excel', icon: '📊' }];
            serialItem.history.push({
              type: "VENTA",
              date: invoiceData.date,
              user: "Sistema Auto-Sigo",
              description: `Vendido automáticamente por reporte de caja Sigo. Factura: ${invoiceData.invoiceNumber}`,
              attachments: [{ name: fileName, type: 'excel', icon: '📊' }]
            });
          }
        }
      }
    });
  });

  if (newInvoicesCount === 0 && duplicateInvoicesCount > 0) {
    addActivityLog("IMPORTACION", "SigoDeduplicationEngine", `Carga rechazada por duplicidad completa en '${fileName}'. Se omitieron ${duplicateInvoicesCount} facturas previamente registradas (${skippedInvoices.join(', ')}).`);
    alert(`⚠️ ATENCIÓN: CANCELADO POR DUPLICIDAD DE REGISTRO\n\n📄 Archivo: ${fileName}\n\nTodas las facturas contenidas en este reporte (${skippedInvoices.join(', ')}) YA fueron registradas anteriormente en el sistema.\n\n🛡️ Se omitieron el 100% de los registros para proteger la línea de tiempo de Sigo y evitar dobles descuentos de inventario.`);
    return;
  }

  addActivityLog("IMPORTACION", "SigoSalesProcessor", `Ingesta de Sigo '${fileName}'. Facturas Nuevas: ${newInvoicesCount} | Duplicadas Omitidas: ${duplicateInvoicesCount} | Clientes Creados: ${newCustomersCreated}`);

  let alertMessage = `🚀 INGESTA AUTOMÁTICA SIGO COMPLETADA:\n\n📄 Archivo: ${fileName}\n🧾 Facturas Nuevas Procesadas: ${newInvoicesCount}\n👤 Clientes Nuevos Creados: ${newCustomersCreated}\n📦 Salidas Descontadas: ${totalExitsRegistered} Unidades.`;
  if (duplicateInvoicesCount > 0) {
    alertMessage += `\n\n🛡️ VALIDACIÓN ANTI-DUPLICIDAD: Se omitieron ${duplicateInvoicesCount} facturas que ya existían previamente (${skippedInvoices.join(', ')}).`;
  }

  alert(alertMessage);

  populateDropdowns();
  renderAllViews();
}

function renderDashboard() {
  document.getElementById("statTotalSkus").textContent = appState.products.length;
  document.getElementById("statPhysicalStock").textContent = appState.products.reduce((acc, p) => acc + p.physicalStock, 0);
  document.getElementById("statReservedStock").textContent = appState.products.reduce((acc, p) => acc + p.reservedStock, 0);
  document.getElementById("statWarrantyItems").textContent = appState.serializedItems.filter(i => i.status === 'EN_GARANTIA' || i.status === 'RETORNO_CHINA').length;

  const tableBody = document.getElementById("dashboardMovementsTable");
  tableBody.innerHTML = appState.movements.slice(0, 5).map(m => {
    const prod = appState.products.find(p => p.id === m.productId);
    const badgeClass = m.type === 'INGRESO_COMPRA' ? 'badge-green' : m.type === 'SALIDA_VENTA' ? 'badge-blue' : 'badge-amber';
    return `
      <tr>
        <td>${m.date}</td>
        <td><span class="badge ${badgeClass}">${m.type}</span></td>
        <td><strong>${prod ? prod.sku : ''}</strong> - ${prod ? prod.name : ''}</td>
        <td><strong>${m.quantity}</strong></td>
        <td>${m.invoiceNumber || '-'}</td>
        <td>${m.user}</td>
      </tr>
    `;
  }).join('');
}

function getProductBrandAndSupplier(p) {
  let brand = p.brand || "";
  let supplier = p.supplier || p.provider || "";

  if (!brand && p.description) {
    const match = p.description.match(/Marca:\s*([^|]+)/i);
    if (match) brand = match[1].trim();
  }
  if (!supplier && p.description) {
    const match = p.description.match(/Prov:\s*([^|]+)/i);
    if (match) supplier = match[1].trim();
  }

  return {
    brand: brand || "General",
    supplier: supplier || "Nacional / Directo"
  };
}

function selectAutocompleteProduct(prodId) {
  const hiddenInput = document.getElementById("movProduct");
  const searchInput = document.getElementById("movProductSearchInput");
  const selectedCard = document.getElementById("movProductSelectedCard");
  const suggestions = document.getElementById("movProductSuggestions");

  if (!hiddenInput) return;

  const product = appState.products.find(p => p.id === prodId);
  if (product) {
    hiddenInput.value = product.id;
    const { brand, supplier } = getProductBrandAndSupplier(product);
    const avail = product.physicalStock - product.reservedStock;

    selectedCard.innerHTML = `
      <div class="selected-product-info">
        <div class="selected-product-title">📦 ${product.sku} - ${product.name}</div>
        <div class="selected-product-sub">
          🏷️ Marca: <strong>${brand}</strong> | 🚚 Prov: <strong>${supplier}</strong> | 📦 Stock: <strong>${product.physicalStock} ${product.unitOfMeasure}</strong> (Disp: <strong>${avail}</strong>)
        </div>
      </div>
      <button type="button" class="btn btn-secondary" style="padding: 0.2rem 0.6rem; font-size: 0.75rem; color: var(--accent-red); border-color: rgba(239,68,68,0.4);" onclick="clearAutocompleteProduct()">
        ✖ Cambiar
      </button>
    `;
    selectedCard.style.display = "flex";
    if (searchInput) {
      searchInput.style.display = "none";
      searchInput.value = "";
    }
    if (suggestions) suggestions.style.display = "none";

    handleProductSelectForMovement();
  }
}

function clearAutocompleteProduct() {
  const hiddenInput = document.getElementById("movProduct");
  const searchInput = document.getElementById("movProductSearchInput");
  const selectedCard = document.getElementById("movProductSelectedCard");
  const suggestions = document.getElementById("movProductSuggestions");

  if (hiddenInput) hiddenInput.value = "";
  if (selectedCard) selectedCard.style.display = "none";
  if (searchInput) {
    searchInput.style.display = "block";
    searchInput.focus();
  }
  if (suggestions) suggestions.style.display = "none";

  handleProductSelectForMovement();
}

let movAutocompleteFilterState = {
  brands: [],
  suppliers: [],
  sort: "sku_asc",
  openPopover: null
};

function toggleInlineFilterPopover(popoverType, event) {
  if (event) event.stopPropagation();
  if (movAutocompleteFilterState.openPopover === popoverType) {
    movAutocompleteFilterState.openPopover = null;
  } else {
    movAutocompleteFilterState.openPopover = popoverType;
  }
  renderMovementProductSuggestions();
}

function toggleInlineBrandFilter(brandVal, event) {
  if (event) event.stopPropagation();
  const idx = movAutocompleteFilterState.brands.indexOf(brandVal);
  if (idx > -1) {
    movAutocompleteFilterState.brands.splice(idx, 1);
  } else {
    movAutocompleteFilterState.brands.push(brandVal);
  }
  renderMovementProductSuggestions();
}

function toggleInlineSupplierFilter(supplierVal, event) {
  if (event) event.stopPropagation();
  const idx = movAutocompleteFilterState.suppliers.indexOf(supplierVal);
  if (idx > -1) {
    movAutocompleteFilterState.suppliers.splice(idx, 1);
  } else {
    movAutocompleteFilterState.suppliers.push(supplierVal);
  }
  renderMovementProductSuggestions();
}

function clearInlineBrandFilters(event) {
  if (event) event.stopPropagation();
  movAutocompleteFilterState.brands = [];
  renderMovementProductSuggestions();
}

function clearInlineSupplierFilters(event) {
  if (event) event.stopPropagation();
  movAutocompleteFilterState.suppliers = [];
  renderMovementProductSuggestions();
}

function renderMovementProductSuggestions() {
  const searchInput = document.getElementById("movProductSearchInput");
  const dropdown = document.getElementById("movProductSuggestions");
  if (!searchInput || !dropdown) return;

  const sortSelect = document.getElementById("movInlineFilterSort");
  if (sortSelect) movAutocompleteFilterState.sort = sortSelect.value;

  const query = searchInput.value.toLowerCase().trim();

  const brandCounts = {};
  const supplierCounts = {};
  appState.products.forEach(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    if (brand) brandCounts[brand] = (brandCounts[brand] || 0) + 1;
    if (supplier) supplierCounts[supplier] = (supplierCounts[supplier] || 0) + 1;
  });

  const sortedBrands = Object.keys(brandCounts).sort();
  const sortedSuppliers = Object.keys(supplierCounts).sort();

  const brandLabel = movAutocompleteFilterState.brands.length === 0 
    ? "🏷️ Marcas (Todas) ▾" 
    : `🏷️ Marcas (${movAutocompleteFilterState.brands.length}) ▾`;

  const supplierLabel = movAutocompleteFilterState.suppliers.length === 0 
    ? "🚚 Prov. (Todos) ▾" 
    : `🚚 Prov. (${movAutocompleteFilterState.suppliers.length}) ▾`;

  let matches = appState.products.filter(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    const matchesQuery = !query || 
      p.sku.toLowerCase().includes(query) ||
      p.name.toLowerCase().includes(query) ||
      brand.toLowerCase().includes(query) ||
      supplier.toLowerCase().includes(query) ||
      (p.description && p.description.toLowerCase().includes(query));

    const matchesBrand = movAutocompleteFilterState.brands.length === 0 || movAutocompleteFilterState.brands.includes(brand);
    const matchesSupplier = movAutocompleteFilterState.suppliers.length === 0 || movAutocompleteFilterState.suppliers.includes(supplier);

    return matchesQuery && matchesBrand && matchesSupplier;
  });

  const sort = movAutocompleteFilterState.sort;
  if (sort === "sku_asc") {
    matches.sort((a, b) => a.sku.localeCompare(b.sku, undefined, { numeric: true }));
  } else if (sort === "sku_desc") {
    matches.sort((a, b) => b.sku.localeCompare(a.sku, undefined, { numeric: true }));
  } else if (sort === "name_asc") {
    matches.sort((a, b) => a.name.localeCompare(b.name));
  } else if (sort === "name_desc") {
    matches.sort((a, b) => b.name.localeCompare(a.name));
  } else if (sort === "stock_desc") {
    matches.sort((a, b) => b.physicalStock - a.physicalStock);
  } else if (sort === "stock_asc") {
    matches.sort((a, b) => a.physicalStock - b.physicalStock);
  }

  matches = matches.slice(0, 15);

  const brandPopoverHtml = movAutocompleteFilterState.openPopover === 'brand' ? `
    <div class="multi-select-popover" onclick="event.stopPropagation()">
      <div style="display: flex; justify-content: space-between; align-items: center; padding-bottom: 0.2rem; border-bottom: 1px solid var(--border-color); margin-bottom: 0.25rem;">
        <span style="font-size: 0.74rem; font-weight: 700; color: var(--accent-green);">Seleccionar Marcas</span>
        <button type="button" class="btn btn-secondary" style="padding: 0.1rem 0.35rem; font-size: 0.68rem;" onclick="clearInlineBrandFilters(event)">Limpiar</button>
      </div>
      ${sortedBrands.map(b => {
        const isChecked = movAutocompleteFilterState.brands.includes(b);
        const safeBrand = b.replace(/'/g, "\\'");
        return `
          <label class="amazon-checkbox-item" onclick="toggleInlineBrandFilter('${safeBrand}', event)">
            <input type="checkbox" ${isChecked ? 'checked' : ''} onclick="event.stopPropagation(); toggleInlineBrandFilter('${safeBrand}', event)">
            <span>${b}</span>
            <span class="amazon-count-badge">(${brandCounts[b]})</span>
          </label>
        `;
      }).join('')}
    </div>
  ` : '';

  const supplierPopoverHtml = movAutocompleteFilterState.openPopover === 'supplier' ? `
    <div class="multi-select-popover" onclick="event.stopPropagation()">
      <div style="display: flex; justify-content: space-between; align-items: center; padding-bottom: 0.2rem; border-bottom: 1px solid var(--border-color); margin-bottom: 0.25rem;">
        <span style="font-size: 0.74rem; font-weight: 700; color: var(--accent-green);">Seleccionar Proveedores</span>
        <button type="button" class="btn btn-secondary" style="padding: 0.1rem 0.35rem; font-size: 0.68rem;" onclick="clearInlineSupplierFilters(event)">Limpiar</button>
      </div>
      ${sortedSuppliers.map(s => {
        const isChecked = movAutocompleteFilterState.suppliers.includes(s);
        const safeSupplier = s.replace(/'/g, "\\'");
        return `
          <label class="amazon-checkbox-item" onclick="toggleInlineSupplierFilter('${safeSupplier}', event)">
            <input type="checkbox" ${isChecked ? 'checked' : ''} onclick="event.stopPropagation(); toggleInlineSupplierFilter('${safeSupplier}', event)">
            <span>${s}</span>
            <span class="amazon-count-badge">(${supplierCounts[s]})</span>
          </label>
        `;
      }).join('')}
    </div>
  ` : '';

  const toolbarHtml = `
    <div style="padding: 0.45rem 0.6rem; background: rgba(15, 23, 42, 0.95); border-bottom: 1px solid var(--border-color); display: flex; gap: 0.35rem; flex-wrap: wrap; align-items: center; justify-content: space-between;">
      <div style="display: flex; gap: 0.35rem; flex: 1; flex-wrap: wrap; align-items: center;">
        
        <div class="multi-select-wrapper">
          <button type="button" class="multi-select-btn" onclick="toggleInlineFilterPopover('brand', event)" style="${movAutocompleteFilterState.brands.length > 0 ? 'border-color: var(--accent-green); background: rgba(16,185,129,0.15);' : ''}">
            ${brandLabel}
          </button>
          ${brandPopoverHtml}
        </div>

        <div class="multi-select-wrapper">
          <button type="button" class="multi-select-btn" onclick="toggleInlineFilterPopover('supplier', event)" style="${movAutocompleteFilterState.suppliers.length > 0 ? 'border-color: var(--accent-green); background: rgba(16,185,129,0.15);' : ''}">
            ${supplierLabel}
          </button>
          ${supplierPopoverHtml}
        </div>

        <select id="movInlineFilterSort" style="padding: 0.2rem 0.4rem; font-size: 0.72rem; background: var(--bg-card); color: var(--text-main); border: 1px solid var(--border-color); border-radius: 4px;" onchange="renderMovementProductSuggestions()">
          <option value="sku_asc" ${sort === 'sku_asc' ? 'selected' : ''}>SKU (A-Z)</option>
          <option value="sku_desc" ${sort === 'sku_desc' ? 'selected' : ''}>SKU (Z-A)</option>
          <option value="name_asc" ${sort === 'name_asc' ? 'selected' : ''}>Nombre (A-Z)</option>
          <option value="stock_desc" ${sort === 'stock_desc' ? 'selected' : ''}>Stock (Mayor)</option>
        </select>
      </div>

      <button type="button" class="btn btn-secondary" style="padding: 0.15rem 0.45rem; font-size: 0.7rem; background: rgba(16,185,129,0.2); border-color: var(--accent-green); color: var(--accent-green);" onclick="openProductSelectorModal()">
        ⚡ Ver Modal
      </button>
    </div>
  `;

  let itemsHtml = '';
  if (matches.length === 0) {
    itemsHtml = `
      <div style="padding: 0.75rem; text-align: center; color: var(--text-muted); font-size: 0.82rem;">
        No se encontraron productos coincidentes.
      </div>
    `;
  } else {
    itemsHtml = matches.map(p => {
      const { brand, supplier } = getProductBrandAndSupplier(p);
      const avail = p.physicalStock - p.reservedStock;
      return `
        <div class="autocomplete-suggestion-item" onclick="selectAutocompleteProduct('${p.id}')">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.15rem;">
            <strong style="color: var(--accent-green); font-family: monospace; font-size: 0.85rem;">${p.sku}</strong>
            <span class="badge ${avail > 0 ? 'badge-green' : 'badge-red'}" style="font-size: 0.7rem;">Stock: ${p.physicalStock} (${avail} disp)</span>
          </div>
          <div style="font-weight: 600; font-size: 0.88rem; color: var(--text-main);">${p.name}</div>
          <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.1rem;">
            🏷️ Marca: <strong>${brand}</strong> | 🚚 Prov: <strong>${supplier}</strong>
          </div>
        </div>
      `;
    }).join('');
  }

  dropdown.innerHTML = toolbarHtml + itemsHtml;
  dropdown.style.display = "block";
}

function initMovementProductAutocomplete() {
  const searchInput = document.getElementById("movProductSearchInput");
  const dropdown = document.getElementById("movProductSuggestions");
  if (!searchInput || !dropdown) return;

  searchInput.addEventListener("input", () => renderMovementProductSuggestions());
  searchInput.addEventListener("focus", () => renderMovementProductSuggestions());

  document.addEventListener("click", (e) => {
    if (!e.target.closest('.multi-select-wrapper') && movAutocompleteFilterState.openPopover) {
      movAutocompleteFilterState.openPopover = null;
      renderMovementProductSuggestions();
    }
    if (!searchInput.contains(e.target) && !dropdown.contains(e.target) && !e.target.closest('#productSelectorModal')) {
      dropdown.style.display = "none";
    }
  });
}

function openProductSelectorModal() {
  const modal = document.getElementById("productSelectorModal");
  if (!modal) return;

  populateModalSidebarFilters();
  renderModalProductList();
  modal.classList.add("active");
}

function closeProductSelectorModal() {
  const modal = document.getElementById("productSelectorModal");
  if (modal) modal.classList.remove("active");
}

function populateModalSidebarFilters() {
  const brandContainer = document.getElementById("modalFilterBrandList");
  const supplierContainer = document.getElementById("modalFilterSupplierList");
  const categoryContainer = document.getElementById("modalFilterCategoryList");

  if (!brandContainer) return;

  const brandCounts = {};
  const supplierCounts = {};
  const categoryCounts = {};

  appState.products.forEach(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    brandCounts[brand] = (brandCounts[brand] || 0) + 1;
    supplierCounts[supplier] = (supplierCounts[supplier] || 0) + 1;

    const categoryObj = appState.categories.find(c => c.id === p.categoryId);
    const catName = categoryObj ? categoryObj.name : (p.category || "General");
    categoryCounts[catName] = (categoryCounts[catName] || 0) + 1;
  });

  brandContainer.innerHTML = Object.keys(brandCounts).sort().map(b => `
    <label class="amazon-checkbox-item">
      <input type="checkbox" class="amazon-filter-chk chk-modal-brand" value="${b}" onchange="renderModalProductList()">
      <span>${b}</span>
      <span class="amazon-count-badge">(${brandCounts[b]})</span>
    </label>
  `).join('');

  supplierContainer.innerHTML = Object.keys(supplierCounts).sort().map(s => `
    <label class="amazon-checkbox-item">
      <input type="checkbox" class="amazon-filter-chk chk-modal-supplier" value="${s}" onchange="renderModalProductList()">
      <span>${s}</span>
      <span class="amazon-count-badge">(${supplierCounts[s]})</span>
    </label>
  `).join('');

  categoryContainer.innerHTML = Object.keys(categoryCounts).sort().map(c => `
    <label class="amazon-checkbox-item">
      <input type="checkbox" class="amazon-filter-chk chk-modal-category" value="${c}" onchange="renderModalProductList()">
      <span>${c}</span>
      <span class="amazon-count-badge">(${categoryCounts[c]})</span>
    </label>
  `).join('');
}

function clearModalProductFilters() {
  document.querySelectorAll('.chk-modal-brand, .chk-modal-supplier, .chk-modal-category').forEach(c => c.checked = false);
  const searchInput = document.getElementById("modalProductSearch");
  const sortSelect = document.getElementById("modalProductSort");
  if (searchInput) searchInput.value = "";
  if (sortSelect) sortSelect.value = "default";
  renderModalProductList();
}

function renderModalProductList() {
  const container = document.getElementById("modalProductList");
  if (!container) return;

  const searchQuery = (document.getElementById("modalProductSearch")?.value || "").toLowerCase().trim();
  const sortOrder = document.getElementById("modalProductSort")?.value || "default";

  const selectedBrands = Array.from(document.querySelectorAll('.chk-modal-brand:checked')).map(c => c.value);
  const selectedSuppliers = Array.from(document.querySelectorAll('.chk-modal-supplier:checked')).map(c => c.value);
  const selectedCategories = Array.from(document.querySelectorAll('.chk-modal-category:checked')).map(c => c.value);

  let filtered = appState.products.filter(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    const categoryObj = appState.categories.find(c => c.id === p.categoryId);
    const catName = categoryObj ? categoryObj.name : (p.category || "General");

    const matchesSearch = !searchQuery ||
      p.sku.toLowerCase().includes(searchQuery) ||
      p.name.toLowerCase().includes(searchQuery) ||
      brand.toLowerCase().includes(searchQuery) ||
      supplier.toLowerCase().includes(searchQuery);

    const matchesBrand = selectedBrands.length === 0 || selectedBrands.includes(brand);
    const matchesSupplier = selectedSuppliers.length === 0 || selectedSuppliers.includes(supplier);
    const matchesCategory = selectedCategories.length === 0 || selectedCategories.includes(catName);

    return matchesSearch && matchesBrand && matchesSupplier && matchesCategory;
  });

  if (sortOrder === "name_asc") {
    filtered.sort((a, b) => a.name.localeCompare(b.name));
  } else if (sortOrder === "name_desc") {
    filtered.sort((a, b) => b.name.localeCompare(a.name));
  } else if (sortOrder === "sku_asc") {
    filtered.sort((a, b) => a.sku.localeCompare(b.sku, undefined, { numeric: true }));
  } else if (sortOrder === "sku_desc") {
    filtered.sort((a, b) => b.sku.localeCompare(a.sku, undefined, { numeric: true }));
  } else if (sortOrder === "stock_desc") {
    filtered.sort((a, b) => b.physicalStock - a.physicalStock);
  } else if (sortOrder === "stock_asc") {
    filtered.sort((a, b) => a.physicalStock - b.physicalStock);
  } else if (sortOrder === "price_desc") {
    filtered.sort((a, b) => b.salePrice - a.salePrice);
  } else if (sortOrder === "price_asc") {
    filtered.sort((a, b) => a.salePrice - b.salePrice);
  }

  if (filtered.length === 0) {
    container.innerHTML = `
      <div style="padding: 2rem; text-align: center; color: var(--text-muted);">
        No se encontraron productos con los filtros seleccionados.
      </div>
    `;
    return;
  }

  container.innerHTML = filtered.map(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    const avail = p.physicalStock - p.reservedStock;
    return `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 0.75rem 1rem; background: var(--bg-card); border: 1px solid var(--border-color); border-radius: var(--radius-md); transition: border-color 0.15s ease;" onmouseover="this.style.borderColor='var(--accent-green)'" onmouseout="this.style.borderColor='var(--border-color)'">
        <div style="display: flex; flex-direction: column; gap: 0.15rem;">
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <strong style="color: var(--accent-green); font-family: monospace; font-size: 0.9rem;">${p.sku}</strong>
            <span class="badge badge-purple" style="font-size: 0.72rem;">${p.category || 'General'}</span>
          </div>
          <div style="font-weight: 700; font-size: 0.95rem; color: var(--text-main);">${p.name}</div>
          <div style="font-size: 0.78rem; color: var(--text-muted);">
            🏷️ Marca: <strong>${brand}</strong> | 🚚 Prov: <strong>${supplier}</strong> | 📦 Physical: <strong>${p.physicalStock}</strong> (Disp: <strong>${avail}</strong>)
          </div>
        </div>
        <button type="button" class="btn btn-primary" style="padding: 0.35rem 0.85rem; font-size: 0.82rem; white-space: nowrap;" onclick="selectProductFromModal('${p.id}')">
          ✓ Seleccionar
        </button>
      </div>
    `;
  }).join('');
}

function selectProductFromModal(prodId) {
  selectAutocompleteProduct(prodId);
  closeProductSelectorModal();
}

function handleCatalogSearchInput() {
  const searchInput = document.getElementById("catalogSearch");
  const dropdown = document.getElementById("catalogSearchDropdown");
  renderCatalog();

  if (!searchInput || !dropdown) return;
  const query = searchInput.value.toLowerCase().trim();
  if (!query) {
    dropdown.style.display = "none";
    return;
  }

  const matches = appState.products.filter(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    return p.sku.toLowerCase().includes(query) ||
           p.name.toLowerCase().includes(query) ||
           brand.toLowerCase().includes(query) ||
           supplier.toLowerCase().includes(query);
  }).slice(0, 8);

  if (matches.length === 0) {
    dropdown.style.display = "none";
    return;
  }

  dropdown.innerHTML = matches.map(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    return `
      <div class="autocomplete-suggestion-item" onclick="selectCatalogSearchSuggestion('${p.sku}')">
        <div style="display: flex; justify-content: space-between; font-size: 0.8rem;">
          <strong style="color: var(--accent-green);">${p.sku}</strong>
          <span style="color: var(--text-muted);">${brand}</span>
        </div>
        <div style="font-weight: 600; font-size: 0.85rem;">${p.name}</div>
      </div>
    `;
  }).join('');

  dropdown.style.display = "block";
}

function selectCatalogSearchSuggestion(sku) {
  const searchInput = document.getElementById("catalogSearch");
  const dropdown = document.getElementById("catalogSearchDropdown");
  if (searchInput) searchInput.value = sku;
  if (dropdown) dropdown.style.display = "none";
  renderCatalog();
}

function populateAmazonSidebarFilters() {
  const brandListContainer = document.getElementById("filterBrandList");
  const supplierListContainer = document.getElementById("filterSupplierList");
  const categoryListContainer = document.getElementById("filterCategoryList");
  const locationListContainer = document.getElementById("filterLocationList");

  if (!brandListContainer) return;

  const brandCounts = {};
  const supplierCounts = {};
  const categoryCounts = {};

  appState.products.forEach(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    brandCounts[brand] = (brandCounts[brand] || 0) + 1;
    supplierCounts[supplier] = (supplierCounts[supplier] || 0) + 1;

    const categoryObj = appState.categories.find(c => c.id === p.categoryId);
    const catName = categoryObj ? categoryObj.name : (p.category || "General");
    categoryCounts[catName] = (categoryCounts[catName] || 0) + 1;
  });

  brandListContainer.innerHTML = Object.keys(brandCounts).sort().map(b => `
    <label class="amazon-checkbox-item">
      <input type="checkbox" class="amazon-filter-chk chk-brand" value="${b}" onchange="renderCatalog()">
      <span>${b}</span>
      <span class="amazon-count-badge">(${brandCounts[b]})</span>
    </label>
  `).join('');

  supplierListContainer.innerHTML = Object.keys(supplierCounts).sort().map(s => `
    <label class="amazon-checkbox-item">
      <input type="checkbox" class="amazon-filter-chk chk-supplier" value="${s}" onchange="renderCatalog()">
      <span>${s}</span>
      <span class="amazon-count-badge">(${supplierCounts[s]})</span>
    </label>
  `).join('');

  categoryListContainer.innerHTML = Object.keys(categoryCounts).sort().map(c => `
    <label class="amazon-checkbox-item">
      <input type="checkbox" class="amazon-filter-chk chk-category" value="${c}" onchange="renderCatalog()">
      <span>${c}</span>
      <span class="amazon-count-badge">(${categoryCounts[c]})</span>
    </label>
  `).join('');

  locationListContainer.innerHTML = appState.locations.map(loc => `
    <label class="amazon-checkbox-item">
      <input type="checkbox" class="amazon-filter-chk chk-location" value="${loc.id}" onchange="renderCatalog()">
      <span>${loc.name}</span>
    </label>
  `).join('');
}

function clearCatalogFilters() {
  document.querySelectorAll('.amazon-filter-chk').forEach(chk => chk.checked = false);
  const searchInput = document.getElementById("catalogSearch");
  const sortSelect = document.getElementById("catalogSortOrder");
  const dropdown = document.getElementById("catalogSearchDropdown");
  if (searchInput) searchInput.value = "";
  if (sortSelect) sortSelect.value = "default";
  if (dropdown) dropdown.style.display = "none";
  renderCatalog();
}

function getSelectedCheckboxValues(selector) {
  return Array.from(document.querySelectorAll(selector + ':checked')).map(cb => cb.value);
}

function toggleCatalogFilterDropdown(e) {
  if (e) e.stopPropagation();
  const card = document.getElementById("catalogFilterDropdownCard");
  if (card) {
    card.classList.toggle("active");
  }
}

function closeCatalogFilterDropdown() {
  const card = document.getElementById("catalogFilterDropdownCard");
  if (card) {
    card.classList.remove("active");
  }
}

function renderCatalog() {
  ensureProductLocations();
  const tableBody = document.getElementById("catalogTableBody");
  const searchQuery = (document.getElementById("catalogSearch")?.value || "").toLowerCase().trim();
  const sortOrder = document.getElementById("catalogSortOrder")?.value || "default";

  const selectedBrands = getSelectedCheckboxValues('.chk-brand');
  const selectedSuppliers = getSelectedCheckboxValues('.chk-supplier');
  const selectedCategories = getSelectedCheckboxValues('.chk-category');
  const selectedLocations = getSelectedCheckboxValues('.chk-location');

  // Update active filter badge counter on toolbar button
  const totalActiveFilters = selectedBrands.length + selectedSuppliers.length + selectedCategories.length + selectedLocations.length;
  const filterBadge = document.getElementById("activeFilterBadgeCount");
  if (filterBadge) {
    if (totalActiveFilters > 0) {
      filterBadge.textContent = totalActiveFilters;
      filterBadge.style.display = "inline-block";
    } else {
      filterBadge.style.display = "none";
    }
  }

  let filtered = appState.products.filter(p => {
    const { brand, supplier } = getProductBrandAndSupplier(p);
    const categoryObj = appState.categories.find(c => c.id === p.categoryId);
    const catName = categoryObj ? categoryObj.name : (p.category || "General");

    const matchesSearch = !searchQuery || 
      p.sku.toLowerCase().includes(searchQuery) || 
      p.name.toLowerCase().includes(searchQuery) ||
      brand.toLowerCase().includes(searchQuery) ||
      supplier.toLowerCase().includes(searchQuery) ||
      (p.barcode && p.barcode.toLowerCase().includes(searchQuery)) ||
      (p.description && p.description.toLowerCase().includes(searchQuery));

    const matchesBrand = selectedBrands.length === 0 || selectedBrands.includes(brand);
    const matchesSupplier = selectedSuppliers.length === 0 || selectedSuppliers.includes(supplier);
    const matchesCategory = selectedCategories.length === 0 || selectedCategories.includes(catName);

    let matchesLocation = true;
    if (selectedLocations.length > 0) {
      matchesLocation = selectedLocations.some(locId => {
        const stockInLoc = (p.stockByLocation && p.stockByLocation[locId]) ? p.stockByLocation[locId] : 0;
        return stockInLoc > 0;
      });
    }

    return matchesSearch && matchesBrand && matchesSupplier && matchesCategory && matchesLocation;
  });

  // Apply Sorting
  if (sortOrder === "name_asc") {
    filtered.sort((a, b) => a.name.localeCompare(b.name));
  } else if (sortOrder === "name_desc") {
    filtered.sort((a, b) => b.name.localeCompare(a.name));
  } else if (sortOrder === "sku_asc") {
    filtered.sort((a, b) => a.sku.localeCompare(b.sku, undefined, { numeric: true }));
  } else if (sortOrder === "sku_desc") {
    filtered.sort((a, b) => b.sku.localeCompare(a.sku, undefined, { numeric: true }));
  } else if (sortOrder === "stock_desc") {
    filtered.sort((a, b) => (b.physicalStock - b.reservedStock) - (a.physicalStock - a.reservedStock));
  } else if (sortOrder === "stock_asc") {
    filtered.sort((a, b) => (a.physicalStock - a.reservedStock) - (b.physicalStock - b.reservedStock));
  } else if (sortOrder === "price_desc") {
    filtered.sort((a, b) => b.salePrice - a.salePrice);
  } else if (sortOrder === "price_asc") {
    filtered.sort((a, b) => a.salePrice - b.salePrice);
  }

  // Update live dynamic counter badge bar
  const counterContainer = document.getElementById("catalogCounterBadge");
  if (counterContainer) {
    const totalPhysicalStock = filtered.reduce((sum, p) => sum + (p.physicalStock || 0), 0);
    const totalCostVal = filtered.reduce((sum, p) => sum + ((p.physicalStock || 0) * (p.baseCost || 0)), 0);
    const totalSaleVal = filtered.reduce((sum, p) => sum + ((p.physicalStock || 0) * (p.salePrice || 0)), 0);
    const isAdmin = isAdminUser(appState.currentUser);

    counterContainer.innerHTML = `
      <span class="badge badge-green" style="font-size: 0.82rem; padding: 0.35rem 0.65rem;">
        📊 Mostrando: <strong>${filtered.length.toLocaleString('es-CO')}</strong> de ${appState.products.length.toLocaleString('es-CO')} productos
      </span>
      <span class="badge badge-blue" style="font-size: 0.82rem; padding: 0.35rem 0.65rem;">
        📦 Existencias Totales: <strong>${totalPhysicalStock.toLocaleString('es-CO')}</strong> unidades
      </span>
      ${isAdmin ? `
        <span class="badge badge-purple" style="font-size: 0.82rem; padding: 0.35rem 0.65rem;">
          💰 Valor Total (Costo): <strong>$${totalCostVal.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</strong>
        </span>
        <span class="badge badge-amber" style="font-size: 0.82rem; padding: 0.35rem 0.65rem;">
          🏷️ Valor Estimado Venta: <strong>$${totalSaleVal.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</strong>
        </span>
      ` : ''}
    `;
  }

  tableBody.innerHTML = filtered.map(p => {
    const availableStock = p.physicalStock - p.reservedStock;
    const isSerialized = p.requiresSerial;
    const categoryObj = appState.categories.find(c => c.id === p.categoryId);
    const categoryName = categoryObj ? categoryObj.name : p.category;

    // Actual count of registered serial numbers in appState.serializedItems
    const registeredSerialsCount = appState.serializedItems.filter(i => i.productId === p.id).length;

    // Build location breakdown pills
    const locationBreakdownHtml = appState.locations.map(loc => {
      const qty = (p.stockByLocation && p.stockByLocation[loc.id]) ? p.stockByLocation[loc.id] : 0;
      const shortLocName = loc.name.replace("Bodega Principal (Central)", "Central").replace("Punto de Venta Bogotá", "PV Bogotá").replace("Almacén Central Llanos", "Llanos");
      return `<span style="font-size: 0.7rem; padding: 0.1rem 0.35rem; background: rgba(15,23,42,0.6); border: 1px solid var(--border-color); border-radius: 4px; display: inline-flex; align-items: center; gap: 0.2rem; white-space: nowrap;">
        📍 ${shortLocName}: <strong style="color: ${qty > 0 ? 'var(--accent-teal)' : 'var(--text-muted)'};">${qty}</strong>
      </span>`;
    }).join(' ');

    return `
      <tr>
        <td><strong style="color: var(--accent-green); font-size: 0.85rem;">${p.sku}</strong></td>
        <td>
          <div style="font-weight: 600; font-size: 0.85rem; color: var(--text-main); margin-bottom: 0.15rem;">${p.name}</div>
          <div style="font-size: 0.73rem; color: var(--text-muted); margin-bottom: 0.25rem;">${p.description || ''}</div>
          <span class="badge badge-purple" style="font-size: 0.7rem; padding: 0.15rem 0.45rem;">${categoryName}</span>
        </td>
        <td>
          <div style="font-size: 0.83rem; font-weight: 700; color: var(--text-main); margin-bottom: 0.3rem; display: flex; align-items: center; gap: 0.4rem; flex-wrap: wrap;">
            <span>📦 Total: <strong>${p.physicalStock}</strong> ${p.unitOfMeasure}</span>
            <span class="badge ${availableStock <= p.minStockAlert ? 'badge-red' : 'badge-green'}" style="font-size: 0.72rem; padding: 0.1rem 0.4rem;" title="Disponible: ${availableStock} | Bloqueado: ${p.reservedStock}">
              ${availableStock} Disp / ${p.reservedStock} Bloq
            </span>
          </div>
          <div style="display: flex; gap: 0.2rem; flex-wrap: wrap;">
            ${locationBreakdownHtml}
          </div>
        </td>
        <td class="cost-column" style="font-size: 0.82rem; font-weight: 500;">$${p.baseCost.toFixed(2)}</td>
        <td class="cost-column" style="font-size: 0.82rem; font-weight: 600; color: var(--accent-green);">$${p.salePrice.toFixed(2)}</td>
        <td style="text-align: center;">
          <div style="display: flex; gap: 0.3rem; justify-content: center; align-items: center; flex-wrap: wrap;">
            ${isAdminUser(appState.currentUser) ? `
              <button class="btn btn-secondary" style="padding: 0.25rem 0.55rem; font-size: 0.75rem; background: rgba(16, 185, 129, 0.18); border-color: rgba(16, 185, 129, 0.4); color: var(--accent-green);" onclick="openEditProductModal('${p.id}')" title="Editar producto e inventario">
                ✏️ Editar
              </button>
            ` : ''}
            ${isSerialized ? `
              <button class="btn btn-secondary" style="padding: 0.25rem 0.55rem; font-size: 0.75rem;" onclick="openSerialInspectorModal('${p.id}')" title="Ver números de serie registrados">
                🔍 Seriales (${registeredSerialsCount})
              </button>
            ` : (!isAdminUser(appState.currentUser) ? '-' : '')}
          </div>
        </td>
      </tr>
    `;
  }).join('');

  toggleFinancialFields(appState.currentUser.role);
}

function openSerialInspectorModal(productId) {
  const product = appState.products.find(p => p.id === productId);
  if (!product) return;

  ensureAllSerialsForProduct(product);
  addActivityLog("CONSULTA", "ProductSerialInspector", `Inspección de seriales para producto '${product.sku}' (${product.physicalStock} existencias).`);

  document.getElementById("inspectorProductName").textContent = `${product.sku} - ${product.name} (${product.physicalStock} Existencias Totales)`;
  
  const inStockItems = appState.serializedItems.filter(i => i.productId === productId && i.status === 'EN_STOCK');
  const exitedItems = appState.serializedItems.filter(i => i.productId === productId && i.status !== 'EN_STOCK');

  const inStockList = document.getElementById("inspectorInStockList");
  if (inStockItems.length === 0) {
    inStockList.innerHTML = `<div style="color: var(--text-muted); padding: 0.5rem;">No hay unidades físicas disponibles en bodega actualmente.</div>`;
  } else {
    inStockList.innerHTML = `
      <div style="font-size: 0.8rem; color: var(--accent-green); margin-bottom: 0.5rem; font-weight: 600;">
        Mostrando los ${inStockItems.length} seriales individuales presentes en bodega:
      </div>
      ${inStockItems.map((item, index) => {
        const locObj = appState.locations.find(l => l.id === item.currentLocationId);
        const locName = locObj ? locObj.name : "Bodega Principal";
        return `
          <div style="background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.3); padding: 0.6rem 0.75rem; border-radius: var(--radius-sm); margin-bottom: 0.4rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 0.5rem;">
            <div>
              <span style="font-size: 0.75rem; color: var(--text-muted); margin-right: 0.4rem;">#${index + 1}</span>
              <strong style="color: var(--accent-green); font-family: monospace; font-size: 0.95rem;">${item.serialNumber}</strong>
              <div style="font-size: 0.73rem; color: var(--text-muted);">
                📍 Ubicación: <strong style="color: var(--accent-teal);">${locName}</strong> | Ingresó: ${item.entryDate}
              </div>
            </div>
            <div style="display: flex; gap: 0.4rem; align-items: center;">
              <span class="badge badge-green">DISPONIBLE</span>
              <button class="btn btn-secondary" style="padding: 0.15rem 0.4rem; font-size: 0.7rem;" onclick="editSerialNumber('${item.id}')" title="Modificar número de serie fábrica">
                ✏️ Editar
              </button>
            </div>
          </div>
        `;
      }).join('')}
    `;
  }

  const exitedList = document.getElementById("inspectorExitedList");
  if (exitedItems.length === 0) {
    exitedList.innerHTML = `<div style="color: var(--text-muted); padding: 0.5rem;">No hay seriales reportados como salidos o vendidos.</div>`;
  } else {
    exitedList.innerHTML = exitedItems.map(item => {
      const customer = appState.customers.find(c => c.id === item.currentCustomerId);
      const attachmentsCount = item.attachments ? item.attachments.length : 0;
      return `
        <div style="background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.3); padding: 0.6rem 0.75rem; border-radius: var(--radius-sm); margin-bottom: 0.4rem;">
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <strong style="color: var(--accent-blue); font-family: monospace; font-size: 0.95rem;">${item.serialNumber}</strong>
            <span class="badge badge-amber">${item.status}</span>
          </div>
          <div style="font-size: 0.78rem; color: var(--text-muted); margin-top: 0.2rem;">
            👤 Cliente: <strong>${customer ? customer.name : 'Venta Directa'}</strong> | Fecha Venta: <strong>${item.saleDate || 'N/A'}</strong> | Factura: <strong>${item.invoiceNumber || 'N/A'}</strong>
          </div>
          ${attachmentsCount > 0 ? `
            <div style="font-size: 0.73rem; color: var(--accent-green); margin-top: 0.2rem;">
              📎 ${attachmentsCount} soportes adjuntos
            </div>
          ` : ''}
          <div style="margin-top: 0.3rem;">
            <button class="btn btn-secondary" style="padding: 0.15rem 0.5rem; font-size: 0.72rem;" onclick="lookupWarrantyBySerial('${item.serialNumber}')">
              🛡️ Consultar Garantía / Devolución
            </button>
          </div>
        </div>
      `;
    }).join('');
  }

  // Populate Serial Registration Panel
  const regPanel = document.getElementById("inspectorRegistrationPanel");
  if (regPanel) {
    if (product.requiresSerial) {
      const totalSerialsCount = appState.serializedItems.filter(i => i.productId === productId).length;
      const unassignedQty = Math.max(0, product.physicalStock - totalSerialsCount);

      regPanel.innerHTML = `
        <div style="background: rgba(16, 185, 129, 0.08); border: 1px solid var(--border-highlight); padding: 0.85rem 1rem; border-radius: var(--radius-md);">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.4rem; flex-wrap: wrap; gap: 0.4rem;">
            <h4 style="font-size: 0.9rem; font-weight: 700; color: var(--accent-green); margin: 0;">
              ➕ Registrar / Cargar Números de Serie
            </h4>
            <span class="badge ${unassignedQty > 0 ? 'badge-amber' : 'badge-green'}" style="font-size: 0.75rem;">
              ${unassignedQty > 0 ? `${unassignedQty} unidades sin serial` : 'Todos los seriales cargados'}
            </span>
          </div>
          <p style="font-size: 0.78rem; color: var(--text-muted); margin-bottom: 0.75rem;">
            Digite o escanee con la cámara (código de barras, QR, DataMatrix, Code 128) el serial único de fábrica para asignarlo al producto.
          </p>

          <div style="display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 0.6rem;">
            <div style="flex: 1; min-width: 160px;">
              <label class="form-label" style="font-size: 0.75rem;">Ubicación / Sede:</label>
              <select id="regSerialLocSelect" class="form-control" style="font-size: 0.82rem; padding: 0.35rem 0.5rem;">
                ${appState.locations.map(l => `<option value="${l.id}">${l.name}</option>`).join('')}
              </select>
            </div>
            <div style="flex: 2; min-width: 200px;">
              <label class="form-label" style="font-size: 0.75rem;">Número de Serie de Fábrica:</label>
              <div style="display: flex; gap: 0.4rem;">
                <input type="text" id="regSerialInput" class="form-control" placeholder="Ej. SN-TED-2026-001" style="font-family: monospace; font-size: 0.85rem; padding: 0.35rem 0.6rem;">
                <button type="button" class="btn btn-camera" style="padding: 0.35rem 0.65rem; font-size: 0.78rem; white-space: nowrap;" onclick="scanSerialForProductRegistration('${product.id}')" title="Escanear Código de Barras / QR con Cámara">
                  📷 Escanear
                </button>
              </div>
            </div>
          </div>

          <button type="button" class="btn btn-primary" onclick="submitRegisterProductSerial('${product.id}')" style="width: 100%; padding: 0.45rem; font-size: 0.85rem;">
            💾 Asignar Serial a Producto
          </button>
        </div>
      `;
    } else {
      regPanel.innerHTML = `
        <div style="background: rgba(100, 116, 139, 0.1); border: 1px solid var(--border-color); padding: 0.65rem 0.85rem; border-radius: var(--radius-md); font-size: 0.8rem; color: var(--text-muted);">
          ℹ️ Este producto está configurado como <strong>Consumible / Desechable (Sin Control por Serial Individual)</strong>. Si desea exigir seriales únicos a cada unidad, active la opción <em>'Requiere Número de Serie'</em> en el formulario de edición del producto.
        </div>
      `;
    }
  }

  document.getElementById("serialInspectorModal").classList.add("active");
}

function editSerialNumber(itemId) {
  const item = appState.serializedItems.find(i => i.id === itemId);
  if (!item) return;

  const newSerial = prompt("Digite el número de serie único asignado por fábrica a esta unidad:", item.serialNumber);
  if (newSerial && newSerial.trim() !== "" && newSerial !== item.serialNumber) {
    const oldSerial = item.serialNumber;
    item.serialNumber = newSerial.trim();
    addActivityLog("MODIFICACION", "SerialUpdate", `Serial '${oldSerial}' modificado manualmente a '${item.serialNumber}'`);
    alert(`✅ Número de serie actualizado a: ${item.serialNumber}`);
    
    const product = appState.products.find(p => p.id === item.productId);
    if (product) openSerialInspectorModal(product.id);
    populateDropdowns();
  }
}

function closeSerialInspectorModal() {
  document.getElementById("serialInspectorModal").classList.remove("active");
}

function lookupWarrantyBySerial(inputSerial = null) {
  const serialQuery = inputSerial || document.getElementById("warrantySerialInput")?.value?.trim();
  const resultsCard = document.getElementById("warrantyResultCard");
  const suggBox = document.getElementById("warrantySerialSuggestions");

  if (suggBox) suggBox.classList.remove("active");

  if (!serialQuery) {
    alert("Por favor digite o escanee un número de serie.");
    return;
  }

  ensureGlobalSerials();
  addActivityLog("GARANTIA", "WarrantyLookup", `Búsqueda e inspección de cobertura de garantía para serial '${serialQuery}'.`);

  let item = appState.serializedItems.find(i => i.serialNumber.toLowerCase() === serialQuery.toLowerCase());
  
  if (!item) {
    item = appState.serializedItems.find(i => i.serialNumber.toLowerCase().includes(serialQuery.toLowerCase()));
  }

  if (!item) {
    resultsCard.style.display = "block";
    resultsCard.innerHTML = `
      <div style="background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.3); padding: 1rem; border-radius: var(--radius-md); color: #fca5a5;">
        ❌ No se encontró ningún equipo en la base de datos registrado con el serial: <strong>${serialQuery}</strong>.
      </div>
    `;
    return;
  }

  const product = appState.products.find(p => p.id === item.productId);
  const customer = appState.customers.find(c => c.id === item.currentCustomerId);

  const warrantyMonths = product ? (product.warrantyMonths || 12) : 12;
  const saleDateObj = item.saleDate ? new Date(item.saleDate) : new Date(item.entryDate);
  const expiryDateObj = new Date(saleDateObj);
  expiryDateObj.setMonth(expiryDateObj.getMonth() + warrantyMonths);

  const today = new Date();
  const isWarrantyValid = (today <= expiryDateObj);
  const daysRemaining = Math.max(0, Math.round((expiryDateObj - today) / (1000 * 60 * 60 * 24)));

  resultsCard.style.display = "block";
  resultsCard.innerHTML = `
    <div style="background: var(--bg-card); border: 1px solid var(--border-highlight); padding: 1.25rem; border-radius: var(--radius-lg);">
      <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 0.5rem; margin-bottom: 1rem;">
        <div>
          <h3 style="font-size: 1.15rem; font-weight: 700;">${product ? product.name : 'Equipo'}</h3>
          <div style="font-size: 0.85rem; color: var(--text-muted);">
            SKU: <strong>${product ? product.sku : ''}</strong> | Serial: <strong style="color: var(--accent-green); font-family: monospace;">${item.serialNumber}</strong>
          </div>
        </div>
        <div>
          <span class="badge ${isWarrantyValid ? 'badge-green' : 'badge-red'}" style="font-size: 0.85rem; padding: 0.4rem 0.8rem;">
            ${isWarrantyValid ? `🛡️ GARANTÍA VIGENTE (${daysRemaining} Días Restantes)` : '❌ GARANTÍA EXPIRADA'}
          </span>
        </div>
      </div>

      <div style="grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); display: grid; gap: 1rem; background: rgba(15, 23, 42, 0.7); padding: 1rem; border-radius: var(--radius-md); margin-bottom: 1rem;">
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted);">Cliente Comprador</div>
          <div style="font-weight: 600; color: var(--text-main);">${customer ? customer.name : 'En Bodega / Sin Cliente'}</div>
          <div style="font-size: 0.75rem; color: var(--text-muted);">${customer ? (customer.documentType + ' ' + customer.documentNumber) : ''}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted);">Factura de Compra</div>
          <div style="font-weight: 600; color: var(--accent-blue);">${item.invoiceNumber || 'Sin Factura'}</div>
          <div style="font-size: 0.75rem; color: var(--text-muted);">Fecha Venta: ${item.saleDate || item.entryDate}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted);">Vencimiento Garantía</div>
          <div style="font-weight: 600;">${expiryDateObj.toISOString().substring(0, 10)}</div>
          <div style="font-size: 0.75rem; color: var(--text-muted);">Cobertura: ${warrantyMonths} Meses</div>
        </div>
      </div>

      <h4 style="font-size: 0.85rem; font-weight: 600; margin-bottom: 0.5rem;">📎 Soportes y Fotografías Adjuntas (Haga clic para ver):</h4>
      <div style="display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 1rem;">
        ${(item.attachments && item.attachments.length > 0) ? item.attachments.map(att => `
          <button class="btn btn-secondary" style="padding: 0.3rem 0.6rem; font-size: 0.8rem;" onclick="previewAttachment('${att.name}', '${att.type || 'image'}', ${att.dataUrl ? `'${att.dataUrl}'` : 'null'})">
            ${att.icon || (att.type === 'pdf' ? '📄' : '📷')} ${att.name}
          </button>
        `).join('') : '<span style="color: var(--text-muted); font-size: 0.8rem;">Sin documentos adjuntos</span>'}
      </div>

      <div style="display: flex; gap: 0.5rem; flex-wrap: wrap;">
        <button class="btn btn-primary" onclick="processWarrantyReturn('${item.id}')">
          🔄 Procesar Devolución / Ingreso por Garantía
        </button>
        <button class="btn btn-secondary" onclick="switchView('view-equipment'); document.getElementById('equipmentSerialSelect').value='${item.id}'; renderEquipmentLifeCycle(); closeSerialInspectorModal();">
          📋 Ver Hoja de Vida Completa
        </button>
      </div>
    </div>
  `;
}

function processWarrantyReturn(serialId) {
  const item = appState.serializedItems.find(i => i.id === serialId);
  if (!item) return;

  const reason = prompt("Describa el motivo del retorno o falla cubierta por garantía:", "Cliente reporta falla de encendido en sonda");
  if (!reason) return;

  item.status = "EN_GARANTIA";
  item.history.push({
    type: "FALLA_REPORTADA",
    date: new Date().toISOString().substring(0, 10),
    user: appState.currentUser.name,
    description: `Retorno por garantía: ${reason}`
  });

  addActivityLog("GARANTIA", "WarrantyReturn", `Recepción de devolución por garantía de serial '${item.serialNumber}'. Motivo: ${reason}`);
  alert(`✅ El equipo ${item.serialNumber} ha sido marcado EN GARANTÍA.`);
  renderAllViews();
  lookupWarrantyBySerial(item.serialNumber);
}

