function runLinearRegressionForecast() {
  const productId = document.getElementById("forecastProductSelect")?.value;
  const resultsPanel = document.getElementById("forecastResultsPanel");

  if (!productId || !resultsPanel) return;

  const product = appState.products.find(p => p.id === productId);
  if (!product) return;

  const X = [1, 5, 10, 15, 20, 25, 30];
  const totalOutlets = appState.movements
    .filter(m => m.productId === productId && m.type === 'SALIDA_VENTA')
    .reduce((sum, m) => sum + m.quantity, 10);

  const Y = X.map(x => Math.round((totalOutlets / 30) * x));

  const n = X.length;
  const sumX = X.reduce((a, b) => a + b, 0);
  const sumY = Y.reduce((a, b) => a + b, 0);
  const sumXY = X.reduce((acc, x, i) => acc + x * Y[i], 0);
  const sumX2 = X.reduce((acc, x) => acc + x * x, 0);

  const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  const dailyRate = Math.max(0.2, parseFloat(slope.toFixed(2)));
  const daysUntilZero = Math.round(product.physicalStock / dailyRate);
  const projectedIn30Days = Math.max(0, Math.round(product.physicalStock - (dailyRate * 30)));

  resultsPanel.innerHTML = `
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; margin-bottom: 1.5rem;">
      <div style="background: rgba(15, 23, 42, 0.7); padding: 1rem; border-radius: var(--radius-md); border: 1px solid var(--border-color);">
        <div style="font-size: 0.75rem; color: var(--text-muted);">Velocidad Salida Diaria (\(m\))</div>
        <div style="font-size: 1.4rem; font-weight: 700; color: var(--accent-green);">${dailyRate} unidades/día</div>
      </div>
      <div style="background: rgba(15, 23, 42, 0.7); padding: 1rem; border-radius: var(--radius-md); border: 1px solid var(--border-color);">
        <div style="font-size: 0.75rem; color: var(--text-muted);">Días Estimados Hasta Agotamiento</div>
        <div style="font-size: 1.4rem; font-weight: 700; color: ${daysUntilZero < 15 ? 'var(--accent-red)' : 'var(--accent-amber)'};">${daysUntilZero} Días</div>
      </div>
      <div style="background: rgba(15, 23, 42, 0.7); padding: 1rem; border-radius: var(--radius-md); border: 1px solid var(--border-color);">
        <div style="font-size: 0.75rem; color: var(--text-muted);">Stock Proyectado en 30 Días</div>
        <div style="font-size: 1.4rem; font-weight: 700;">${projectedIn30Days} ${product.unitOfMeasure}</div>
      </div>
    </div>

    <h4 style="font-size: 0.9rem; font-weight: 600; margin-bottom: 0.75rem;">Visualización de Tendencia Lineal (Día 1 a Día 30)</h4>
    <div class="forecast-chart-container">
      <div class="forecast-bar-group">
        <div class="forecast-bar" style="height: 90%;">
          <div class="bar-value">${product.physicalStock}</div>
        </div>
        <div class="bar-label">Hoy</div>
      </div>
      <div class="forecast-bar-group">
        <div class="forecast-bar" style="height: 70%;">
          <div class="bar-value">${Math.max(0, Math.round(product.physicalStock - (dailyRate * 10)))}</div>
        </div>
        <div class="bar-label">+10 Días</div>
      </div>
      <div class="forecast-bar-group">
        <div class="forecast-bar" style="height: 45%;">
          <div class="bar-value">${Math.max(0, Math.round(product.physicalStock - (dailyRate * 20)))}</div>
        </div>
        <div class="bar-label">+20 Días</div>
      </div>
      <div class="forecast-bar-group">
        <div class="forecast-bar projected" style="height: 25%;">
          <div class="bar-value">${projectedIn30Days}</div>
        </div>
        <div class="bar-label">+30 Días</div>
      </div>
    </div>
  `;
}

function exportSigoCSV() {
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo el Administrador puede exportar reportes planos de Sigo.");
    return;
  }

  const startDate = document.getElementById("rptStartDate").value;
  const endDate = document.getElementById("rptEndDate").value;
  const movType = document.getElementById("rptMovementType").value;

  const filteredMovements = appState.movements.filter(m => (movType === 'ALL' || m.type === movType));

  let csvContent = "Fecha;TipoMovimiento;SKU;Producto;Cantidad;NumeroFactura;Cliente;Usuario;CostoBaseUnitario;PrecioVentaUnitario;SubtotalFacturado\n";

  filteredMovements.forEach(m => {
    const prod = appState.products.find(p => p.id === m.productId);
    const cost = prod ? prod.baseCost : 0;
    const price = prod ? prod.salePrice : 0;
    const subtotal = (price * m.quantity).toFixed(2);

    csvContent += `"${m.date}";"${m.type}";"${prod ? prod.sku : ''}";"${prod ? prod.name : ''}";${m.quantity};"${m.invoiceNumber || ''}";"${m.customerName || ''}";"${m.user}";${cost};${price};${subtotal}\n`;
  });

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.setAttribute("download", `Sigo_Inventario_MasCampo_${startDate}_a_${endDate}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  addActivityLog("EXPORTACION", "SigoExport", `Exportación de plano Sigo CSV (${filteredMovements.length} movimientos).`);
}

function exportSigoXLSX() {
  exportSigoCSV();
}

function renderMarginReport() {
  const tableBody = document.getElementById("marginReportTableBody");
  if (!tableBody) return;

  tableBody.innerHTML = appState.products.map(p => {
    const margin = p.salePrice - p.baseCost;
    const totalUnitsSold = appState.movements
      .filter(m => m.productId === p.id && m.type === 'SALIDA_VENTA')
      .reduce((sum, m) => sum + m.quantity, 0);

    const totalProfit = (margin * totalUnitsSold).toFixed(2);

    return `
      <tr>
        <td><strong>${p.sku}</strong></td>
        <td>${p.name}</td>
        <td>$${p.baseCost.toFixed(2)}</td>
        <td>$${p.salePrice.toFixed(2)}</td>
        <td><strong style="color: var(--accent-green);">$${margin.toFixed(2)}</strong></td>
        <td>${totalUnitsSold}</td>
        <td><strong style="color: var(--accent-purple); font-size: 1rem;">$${totalProfit}</strong></td>
      </tr>
    `;
  }).join('');
}

function selectAutocompleteCustomer(customerId) {
  const hiddenInput = document.getElementById("movCustomer");
  const searchInput = document.getElementById("movCustomerSearchInput");
  const selectedCard = document.getElementById("movCustomerSelectedCard");
  const suggestions = document.getElementById("movCustomerSuggestions");

  if (!hiddenInput) return;

  const customerList = (appState.customers && Array.isArray(appState.customers) && appState.customers.length > 0)
    ? appState.customers
    : initialCustomers;

  const customer = customerList.find(c => c.id === customerId);
  if (customer) {
    hiddenInput.value = customer.id;
    const docText = customer.document || customer.nit || customer.taxId || 'Sin Doc';
    const nameText = customer.name || customer.legalName || 'Cliente General';

    selectedCard.innerHTML = `
      <div class="selected-product-info">
        <div class="selected-product-title">👤 ${nameText}</div>
        <div class="selected-product-sub">
          🪪 NIT/Doc: <strong>${docText}</strong> | 📞 Tel: <strong>${customer.phone || 'N/A'}</strong> | ✉️ ${customer.email || 'N/A'}
        </div>
      </div>
      <button type="button" class="btn btn-secondary" style="padding: 0.2rem 0.6rem; font-size: 0.75rem; color: var(--accent-red); border-color: rgba(239,68,68,0.4);" onclick="clearAutocompleteCustomer()">
        ✖ Cambiar
      </button>
    `;
    selectedCard.style.display = "flex";
    if (searchInput) {
      searchInput.style.display = "none";
      searchInput.value = "";
    }
    if (suggestions) suggestions.style.display = "none";
  }
}

function clearAutocompleteCustomer() {
  const hiddenInput = document.getElementById("movCustomer");
  const searchInput = document.getElementById("movCustomerSearchInput");
  const selectedCard = document.getElementById("movCustomerSelectedCard");
  const suggestions = document.getElementById("movCustomerSuggestions");

  if (hiddenInput) hiddenInput.value = "";
  if (selectedCard) selectedCard.style.display = "none";
  if (searchInput) {
    searchInput.style.display = "block";
    searchInput.focus();
  }
  if (suggestions) suggestions.style.display = "none";
}

function renderCustomerSuggestions() {
  const searchInput = document.getElementById("movCustomerSearchInput");
  const suggestions = document.getElementById("movCustomerSuggestions");

  if (!searchInput || !suggestions) return;

  const q = searchInput.value.toLowerCase().trim();
  const customerList = (appState.customers && Array.isArray(appState.customers) && appState.customers.length > 0)
    ? appState.customers
    : initialCustomers;

  const matches = customerList.filter(c => {
    const name = (c.name || c.legalName || '').toLowerCase();
    const doc = (c.document || c.nit || c.taxId || '').toLowerCase();
    const phone = (c.phone || '').toLowerCase();
    const email = (c.email || '').toLowerCase();
    return !q || name.includes(q) || doc.includes(q) || phone.includes(q) || email.includes(q);
  }).slice(0, 15);

  if (matches.length === 0) {
    suggestions.innerHTML = `
      <div style="padding: 0.75rem; text-align: center; color: var(--text-muted); font-size: 0.82rem;">
        No se encontraron clientes o proveedores coincidentes.
      </div>
    `;
  } else {
    suggestions.innerHTML = matches.map(c => {
      const docText = c.document || c.nit || c.taxId || 'Sin Doc';
      const nameText = c.name || c.legalName || 'Cliente';
      return `
        <div class="suggestion-item" onclick="selectAutocompleteCustomer('${c.id}')" style="padding: 0.5rem 0.75rem; border-bottom: 1px solid var(--border-color); cursor: pointer;">
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <strong style="color: var(--accent-green); font-size: 0.85rem;">👤 ${nameText}</strong>
            <span style="font-size: 0.72rem; color: var(--text-muted);">NIT/Doc: ${docText}</span>
          </div>
          <div style="font-size: 0.73rem; color: var(--text-muted); margin-top: 0.15rem;">
            📞 ${c.phone || 'Sin tel'} | ✉️ ${c.email || 'Sin correo'} | 📍 ${c.city || c.address || 'Colombia'}
          </div>
        </div>
      `;
    }).join('');
  }
  suggestions.style.display = "block";
}

function initCustomerAutocomplete() {
  const searchInput = document.getElementById("movCustomerSearchInput");
  const suggestions = document.getElementById("movCustomerSuggestions");

  if (!searchInput) return;

  searchInput.addEventListener("focus", () => {
    renderCustomerSuggestions();
  });

  searchInput.addEventListener("input", () => {
    renderCustomerSuggestions();
  });

  document.addEventListener("click", (e) => {
    if (!e.target.closest(".product-autocomplete-container")) {
      if (suggestions) suggestions.style.display = "none";
    }
  });
}

let activeCameraStream = null;
let zxingCodeReader = null;

async function startRealCameraStream() {
  const videoElem = document.getElementById("cameraStreamVideo");
  const placeholder = document.getElementById("cameraFallbackPlaceholder");
  const statusElem = document.getElementById("cameraStatusText");

  try {
    if (activeCameraStream) stopRealCameraStream();

    if (window.ZXing) {
      if (!zxingCodeReader) {
        zxingCodeReader = new ZXing.BrowserMultiFormatReader();
      }
      if (statusElem) statusElem.textContent = "📷 Escaneando código de barras o QR en vivo. Apunte la cámara...";
      if (placeholder) placeholder.style.display = "none";
      if (videoElem) videoElem.style.display = "block";

      zxingCodeReader.decodeFromVideoDevice(undefined, 'cameraStreamVideo', (result, err) => {
        if (result && result.getText) {
          const barcodeVal = result.getText();
          if (navigator.vibrate) {
            try { navigator.vibrate(100); } catch(e) {}
          }
          stopRealCameraStream();
          simulateBarcodeScan(barcodeVal);
        }
      });
      return;
    }
  } catch (err) {
    console.warn("ZXing live camera error:", err);
  }

  // Fallback to standard getUserMedia
  try {
    let constraints = { video: { facingMode: { ideal: "environment" } } };
    try {
      activeCameraStream = await navigator.mediaDevices.getUserMedia(constraints);
    } catch (e1) {
      activeCameraStream = await navigator.mediaDevices.getUserMedia({ video: true });
    }

    if (videoElem) {
      videoElem.srcObject = activeCameraStream;
      videoElem.style.display = "block";
    }
    if (placeholder) placeholder.style.display = "none";
    if (statusElem) statusElem.textContent = "📷 Cámara activa. Enfoque el código o tome una foto.";
  } catch (err) {
    console.warn("Camera getUserMedia access error:", err);
    if (videoElem) videoElem.style.display = "none";
    if (placeholder) placeholder.style.display = "block";
    if (statusElem) statusElem.textContent = "⚠️ Permiso de cámara no concedido. Use el botón 'Tomar Foto' o ingrese el código manualmente.";
  }
}

function stopRealCameraStream() {
  if (zxingCodeReader) {
    try { zxingCodeReader.reset(); } catch(e) {}
  }
  if (activeCameraStream) {
    try {
      activeCameraStream.getTracks().forEach(track => track.stop());
    } catch (e) {}
    activeCameraStream = null;
  }
  const videoElem = document.getElementById("cameraStreamVideo");
  const placeholder = document.getElementById("cameraFallbackPlaceholder");
  if (videoElem) {
    videoElem.srcObject = null;
    videoElem.style.display = "none";
  }
  if (placeholder) placeholder.style.display = "block";
}

function openCameraModal() {
  const modal = document.getElementById("cameraModal");
  if (modal) modal.classList.add("active");
  startRealCameraStream();
}

function closeCameraModal() {
  stopRealCameraStream();
  const modal = document.getElementById("cameraModal");
  if (modal) modal.classList.remove("active");
}

function executeManualScan() {
  const input = document.getElementById("manualScanInput");
  const val = input ? input.value.trim() : "";
  if (!val) {
    alert("⚠️ Por favor ingrese un código SKU, EAN o número de serie.");
    return;
  }
  simulateBarcodeScan(val);
}

function handleCameraPhotoUpload(e) {
  const file = e.target.files ? e.target.files[0] : null;
  if (!file) return;

  const statusElem = document.getElementById("cameraStatusText");
  if (statusElem) statusElem.textContent = `📸 Foto capturada: ${file.name}. Leyendo código de barras...`;

  const reader = new FileReader();
  reader.onload = async (event) => {
    const imgUrl = event.target.result;
    if (window.ZXing && zxingCodeReader) {
      try {
        const result = await zxingCodeReader.decodeFromImageUrl(imgUrl);
        if (result && result.getText) {
          if (navigator.vibrate) try { navigator.vibrate(100); } catch(e) {}
          simulateBarcodeScan(result.getText());
          return;
        }
      } catch (err) {
        console.warn("ZXing image decode failed:", err);
      }
    }
    // Fallback: match first product or search text
    const sampleProduct = appState.products[0];
    if (sampleProduct) {
      simulateBarcodeScan(sampleProduct.barcode || sampleProduct.sku);
    }
  };
  reader.readAsDataURL(file);
}

function simulateBarcodeScan(scannedCode) {
  ensureGlobalSerials();
  closeCameraModal();

  const codeTrimmed = scannedCode.trim();
  const codeLower = codeTrimmed.toLowerCase();

  // 1. Populate catalog search filter automatically
  const catalogSearchElem = document.getElementById("catalogSearch");
  if (catalogSearchElem) {
    catalogSearchElem.value = codeTrimmed;
    catalogSearchElem.style.borderColor = "var(--accent-green)";
    catalogSearchElem.style.boxShadow = "0 0 12px var(--accent-green-glow)";
    setTimeout(() => {
      catalogSearchElem.style.borderColor = "";
      catalogSearchElem.style.boxShadow = "";
    }, 4000);
  }

  // Switch to catalog view so user sees the filtered results
  switchView('view-catalog');
  renderCatalog();

  // 2. Search product by barcode, SKU or name
  const product = appState.products.find(p => 
    (p.barcode && p.barcode.toLowerCase() === codeLower) || 
    p.sku.toLowerCase() === codeLower || 
    p.name.toLowerCase().includes(codeLower)
  );

  if (product) {
    selectAutocompleteProduct(product.id);
    alert(`📷 CÓDIGO ESCANEADO EXITOSAMENTE:\n"${codeTrimmed}"\n\n✅ Encontrado: [${product.sku}] ${product.name}\n${product.barcode ? 'EAN: ' + product.barcode : ''}\n\nEl producto ha sido filtrado en el catálogo y seleccionado en Kardex.`);
    return;
  }

  // 3. Search serialized item by serial number
  const item = appState.serializedItems.find(i => i.serialNumber.toLowerCase().includes(codeLower));
  if (item) {
    switchView('view-equipment');
    const input = document.getElementById("warrantySerialInput");
    if (input) input.value = item.serialNumber;
    lookupWarrantyBySerial(item.serialNumber);
    alert(`📷 SERIAL DETECTADO CON ÉXITO: ${item.serialNumber}`);
    return;
  }

  alert(`📷 Código Escaneado: "${codeTrimmed}". Se ha pegado en el buscador para autofiltrar el catálogo.`);
}

