function handleCreateProduct(e) {
  e.preventDefault();
  const sku = document.getElementById("newSku").value.trim();
  const barcode = document.getElementById("newBarcode") ? document.getElementById("newBarcode").value.trim() : "";
  const name = document.getElementById("newName").value.trim();
  const categoryId = document.getElementById("newCategory").value;
  const unit = document.getElementById("newUnit").value;
  const reqSerial = document.getElementById("newReqSerial").value === "true";
  const minStock = parseInt(document.getElementById("newMinStock").value) || 0;
  const baseCost = parseFloat(document.getElementById("newBaseCost").value) || 0;
  const salePrice = parseFloat(document.getElementById("newSalePrice").value) || 0;

  const categoryObj = appState.categories.find(c => c.id === categoryId);

  const newProd = {
    id: `prod-${Date.now()}`,
    sku,
    barcode,
    name,
    description: "Ingresado manualmente al catálogo",
    categoryId,
    category: categoryObj ? categoryObj.name : "General",
    requiresSerial: reqSerial,
    unitOfMeasure: unit,
    minStockAlert: minStock,
    baseCost,
    salePrice,
    physicalStock: 0,
    reservedStock: 0,
    warrantyMonths: reqSerial ? 12 : 0
  };

  appState.products.push(newProd);
  addActivityLog("CREACION", "ProductManagement", `Creación de producto nuevo en catálogo '${sku} - ${name}' (Barcode: ${barcode || 'N/A'})`);

  alert(`✅ Producto ${sku} creado.`);
  closeProductModal();
  populateDropdowns();
  renderAllViews();
}

function openEditProductModal(productId) {
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo Administradores y Superadministradores pueden editar información de productos e inventario.");
    return;
  }

  const product = appState.products.find(p => p.id === productId);
  if (!product) {
    alert("❌ Producto no encontrado.");
    return;
  }

  const editTitle = document.getElementById("editProductTitle");
  if (editTitle) {
    editTitle.textContent = `✏️ Editar Ficha: [${product.sku}] ${product.name}`;
  }

  document.getElementById("editProductId").value = product.id;
  document.getElementById("editSku").value = product.sku || "";
  if (document.getElementById("editBarcode")) {
    document.getElementById("editBarcode").value = product.barcode || "";
  }
  document.getElementById("editName").value = product.name || "";
  document.getElementById("editDescription").value = product.description || "";
  document.getElementById("editUnit").value = product.unitOfMeasure || "UNIDAD";
  document.getElementById("editBaseCost").value = (product.baseCost !== undefined) ? product.baseCost : 0;
  document.getElementById("editSalePrice").value = (product.salePrice !== undefined) ? product.salePrice : 0;
  document.getElementById("editPhysicalStock").value = (product.physicalStock !== undefined) ? product.physicalStock : 0;
  document.getElementById("editReservedStock").value = (product.reservedStock !== undefined) ? product.reservedStock : 0;
  document.getElementById("editMinStock").value = (product.minStockAlert !== undefined) ? product.minStockAlert : 5;
  document.getElementById("editWarrantyMonths").value = (product.warrantyMonths !== undefined) ? product.warrantyMonths : 0;
  document.getElementById("editReqSerial").value = product.requiresSerial ? "true" : "false";

  // Populate Categories
  const categorySelect = document.getElementById("editCategory");
  if (categorySelect) {
    categorySelect.innerHTML = appState.categories.map(c => 
      `<option value="${c.id}" ${c.id === product.categoryId ? 'selected' : ''}>${c.name}</option>`
    ).join('');
  }

  // Populate Stock by Location Container
  ensureProductLocations();
  const stockByLoc = product.stockByLocation || {};
  const container = document.getElementById("editProductStockByLocationContainer");
  if (container) {
    container.innerHTML = appState.locations.map(loc => {
      const qty = stockByLoc[loc.id] !== undefined ? stockByLoc[loc.id] : 0;
      return `
        <div class="form-row" style="margin-bottom: 0.4rem; align-items: center;">
          <div style="font-size: 0.85rem; font-weight: 600; color: var(--text-main); flex: 1;">📍 ${loc.name}</div>
          <input type="number" min="0" class="form-control edit-loc-stock-input" data-loc-id="${loc.id}" value="${qty}" onchange="recalculateTotalStockFromLocations()" style="padding: 0.3rem 0.5rem; max-width: 130px;">
        </div>
      `;
    }).join('');
  }

  // Populate Section 4: Serials in Ficha
  toggleFichaSerialSection();

  switchView('view-edit-product');
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function toggleFichaSerialSection() {
  const reqSelect = document.getElementById("editReqSerial");
  const section = document.getElementById("editProductSerialsSection");
  if (!reqSelect || !section) return;

  if (reqSelect.value === "true") {
    section.style.display = "block";
    const productId = document.getElementById("editProductId")?.value;
    if (productId) {
      const product = appState.products.find(p => p.id === productId);
      if (product) renderFichaSerials(product);
    }
  } else {
    section.style.display = "none";
  }
}

function renderFichaSerials(product) {
  const container = document.getElementById("editProductSerialsContainer");
  if (!container) return;

  const serials = appState.serializedItems.filter(i => i.productId === product.id && i.status === 'EN_STOCK');

  let totalStock = product.physicalStock || 0;
  if (totalStock === 0 && document.querySelectorAll(".edit-loc-stock-input").length > 0) {
    document.querySelectorAll(".edit-loc-stock-input").forEach(inp => totalStock += parseInt(inp.value) || 0);
  }

  const rowsCount = Math.max(totalStock, serials.length);

  if (rowsCount === 0) {
    container.innerHTML = `<div style="color: var(--text-muted); font-size: 0.82rem; padding: 0.5rem;">⚠️ No hay existencias físicas en stock. Incremente la cantidad por sede arriba para habilitar casillas de serial.</div>`;
    return;
  }

  let html = '';
  for (let i = 0; i < rowsCount; i++) {
    const item = serials[i];
    const sValue = item ? item.serialNumber : '';
    const locId = item ? item.currentLocationId : (appState.locations[0] ? appState.locations[0].id : 'loc-1');

    html += `
      <div class="form-row ficha-serial-row" style="align-items: center; gap: 0.5rem; margin-bottom: 0.35rem;">
        <div style="font-size: 0.78rem; color: var(--text-muted); width: 32px; text-align: right;">#${i + 1}</div>
        <div style="flex: 1; min-width: 150px;">
          <select class="form-control ficha-serial-loc-select" style="font-size: 0.8rem; padding: 0.3rem 0.5rem;">
            ${appState.locations.map(l => `<option value="${l.id}" ${l.id === locId ? 'selected' : ''}>${l.name}</option>`).join('')}
          </select>
        </div>
        <div style="flex: 2; min-width: 200px; display: flex; gap: 0.4rem;">
          <input type="text" class="form-control ficha-serial-num-input" value="${sValue}" placeholder="Serial Único (Ej. SN-TED-2026-${String(i+1).padStart(3, '0')})" style="font-family: monospace; font-size: 0.85rem; padding: 0.3rem 0.5rem;" data-original-id="${item ? item.id : ''}">
          <button type="button" class="btn btn-camera" style="padding: 0.3rem 0.6rem; font-size: 0.75rem; white-space: nowrap;" onclick="scanFichaSerialInput(this)">
            📷 Escanear
          </button>
        </div>
      </div>
    `;
  }

  container.innerHTML = html;
}

function addFichaSerialRow() {
  const container = document.getElementById("editProductSerialsContainer");
  if (!container) return;

  const count = container.querySelectorAll(".ficha-serial-row").length + 1;
  const newRow = document.createElement("div");
  newRow.className = "form-row ficha-serial-row";
  newRow.style.cssText = "align-items: center; gap: 0.5rem; margin-bottom: 0.35rem;";
  newRow.innerHTML = `
    <div style="font-size: 0.78rem; color: var(--text-muted); width: 32px; text-align: right;">#${count}</div>
    <div style="flex: 1; min-width: 150px;">
      <select class="form-control ficha-serial-loc-select" style="font-size: 0.8rem; padding: 0.3rem 0.5rem;">
        ${appState.locations.map(l => `<option value="${l.id}">${l.name}</option>`).join('')}
      </select>
    </div>
    <div style="flex: 2; min-width: 200px; display: flex; gap: 0.4rem;">
      <input type="text" class="form-control ficha-serial-num-input" value="" placeholder="Serial Único de Fábrica" style="font-family: monospace; font-size: 0.85rem; padding: 0.3rem 0.5rem;" data-original-id="">
      <button type="button" class="btn btn-camera" style="padding: 0.3rem 0.6rem; font-size: 0.75rem; white-space: nowrap;" onclick="scanFichaSerialInput(this)">
        📷 Escanear
      </button>
    </div>
  `;

  if (container.children.length === 1 && !container.children[0].classList.contains("ficha-serial-row")) {
    container.innerHTML = "";
  }
  container.appendChild(newRow);
}

function scanFichaSerialInput(btnBtn) {
  const input = btnBtn.previousElementSibling;
  startCameraScanner((code) => {
    if (input) input.value = code;
  });
}

function recalculateTotalStockFromLocations() {
  let total = 0;
  document.querySelectorAll(".edit-loc-stock-input").forEach(input => {
    total += parseInt(input.value) || 0;
  });
  const totalInput = document.getElementById("editPhysicalStock");
  if (totalInput) totalInput.value = total;

  const productId = document.getElementById("editProductId")?.value;
  if (productId) {
    const product = appState.products.find(p => p.id === productId);
    if (product) renderFichaSerials(product);
  }
}

function closeEditProductModal() {
  switchView('view-catalog');
}

function handleUpdateProduct(e) {
  e.preventDefault();
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo Administradores y Superadministradores pueden guardar cambios en productos.");
    return;
  }

  const productId = document.getElementById("editProductId").value;
  const product = appState.products.find(p => p.id === productId);
  if (!product) {
    alert("❌ Producto no encontrado.");
    return;
  }

  const sku = document.getElementById("editSku").value.trim();
  const barcode = document.getElementById("editBarcode") ? document.getElementById("editBarcode").value.trim() : "";
  const name = document.getElementById("editName").value.trim();
  const description = document.getElementById("editDescription").value.trim();
  const categoryId = document.getElementById("editCategory").value;
  const unitOfMeasure = document.getElementById("editUnit").value;
  const baseCost = parseFloat(document.getElementById("editBaseCost").value) || 0;
  const salePrice = parseFloat(document.getElementById("editSalePrice").value) || 0;
  const reservedStock = parseInt(document.getElementById("editReservedStock").value) || 0;
  const minStockAlert = parseInt(document.getElementById("editMinStock").value) || 0;
  const warrantyMonths = parseInt(document.getElementById("editWarrantyMonths").value) || 0;
  const requiresSerial = document.getElementById("editReqSerial").value === "true";

  const categoryObj = appState.categories.find(c => c.id === categoryId);

  // Collect Stock by Location and recalculate physicalStock
  let physicalStock = 0;
  const stockByLocation = {};
  document.querySelectorAll(".edit-loc-stock-input").forEach(input => {
    const locId = input.getAttribute("data-loc-id");
    const val = parseInt(input.value) || 0;
    stockByLocation[locId] = val;
    physicalStock += val;
  });

  // Update object properties
  product.sku = sku;
  product.barcode = barcode;
  product.name = name;
  product.description = description;
  product.categoryId = categoryId;
  product.category = categoryObj ? categoryObj.name : "General";
  product.unitOfMeasure = unitOfMeasure;
  product.baseCost = baseCost;
  product.salePrice = salePrice;
  product.physicalStock = physicalStock;
  product.reservedStock = reservedStock;
  product.minStockAlert = minStockAlert;
  product.warrantyMonths = warrantyMonths;
  product.requiresSerial = requiresSerial;
  product.stockByLocation = stockByLocation;

  // Save/Update Serials from Product Ficha
  if (requiresSerial) {
    const serialRows = document.querySelectorAll(".ficha-serial-row");
    serialRows.forEach(row => {
      const input = row.querySelector(".ficha-serial-num-input");
      const locSelect = row.querySelector(".ficha-serial-loc-select");
      if (input && input.value.trim()) {
        const sNum = input.value.trim().toUpperCase();
        const origId = input.getAttribute("data-original-id");
        const lId = locSelect ? locSelect.value : "loc-1";

        if (origId) {
          const item = appState.serializedItems.find(i => i.id === origId);
          if (item) {
            item.serialNumber = sNum;
            item.currentLocationId = lId;
          }
        } else {
          let existingItem = appState.serializedItems.find(i => i.serialNumber === sNum);
          if (!existingItem) {
            appState.serializedItems.push({
              id: `ser-${Date.now()}-${Math.floor(Math.random()*1000)}`,
              productId: product.id,
              serialNumber: sNum,
              status: "EN_STOCK",
              currentLocationId: lId,
              currentCustomerId: null,
              entryDate: new Date().toISOString().split("T")[0],
              saleDate: null,
              invoiceNumber: null,
              attachments: [],
              history: [{
                type: "INGRESO_FICHA",
                date: new Date().toISOString().split("T")[0],
                user: appState.currentUser ? appState.currentUser.name : "Administrador",
                description: "Carga de serial individual desde la Ficha de Información del Producto."
              }]
            });
          }
        }
      }
    });
  }

  // Record audit log entry
  addActivityLog("EDICION_PRODUCTO", "ProductManagement", `Modificación completa de producto e inventario '${sku} - ${name}' (Barcode: ${barcode || 'N/A'}) por usuario '${appState.currentUser.name || appState.currentUser.email}'`);

  alert(`✅ Producto '${sku} - ${name}' e inventario actualizados exitosamente.`);
  switchView('view-catalog');
  populateDropdowns();
  renderAllViews();
}

function openReservationModal() {
  document.getElementById("reservationModal").classList.add("active");
}

function closeReservationModal() {
  document.getElementById("reservationModal").classList.remove("active");
}

function handleExcelUpload(event) {
  const file = event.target.files[0];
  if (!file) return;

  addActivityLog("IMPORTACION", "ExcelImporter", `Carga manual de archivo de datos Excel '${file.name}'.`);
  alert(`✅ ¡Archivo Excel '${file.name}' cargado con éxito!`);
  renderAllViews();
}

// ==========================================================================
// PENDING INVENTORY INTAKE VALIDATION ENGINE (LOGISTICA SUBMISSION & ADMIN APPROVAL)
// ==========================================================================

const initialPendingIntakes = [
  {
    id: "intake-101",
    submittedAt: "2026-08-15 11:20:00",
    submittedBy: "Jorge Ramos (Logística)",
    userEmail: "logistica@mascampo.co",
    productId: "prod-101",
    sku: "TERM-DIG-01",
    productName: "Termómetro Digital Veterinario HD",
    locationId: "loc-1",
    locationName: "Bodega Principal (Central)",
    proposedQuantity: 50,
    requiresSerial: true,
    proposedSerials: ["SN-TERM-2026-X01", "SN-TERM-2026-X02", "SN-TERM-2026-X03"],
    invoiceNumber: "FAC-REM-8812",
    notes: "Llegada parcial de 50 unidades enviadas por proveedor de laboratorio",
    status: "PENDIENTE_VALIDACION"
  }
];

function loadPersistedPendingIntakes() {
  try {
    const saved = localStorage.getItem("mascampo_pending_intakes_db");
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        appState.pendingIntakes = parsed;
        return;
      }
    }
  } catch (e) {
    console.warn("No se pudo cargar solicitudes de ingreso pendientes", e);
  }
  appState.pendingIntakes = [...initialPendingIntakes];
}

function savePendingIntakesToDisk() {
  try {
    localStorage.setItem("mascampo_pending_intakes_db", JSON.stringify(appState.pendingIntakes));
  } catch (e) {
    console.error("Error guardando ingresos pendientes en disco", e);
  }
}

function renderPendingValidationsView() {
  if (!appState.pendingIntakes) appState.pendingIntakes = [];

  const pendingCount = appState.pendingIntakes.filter(i => i.status === 'PENDIENTE_VALIDACION').length;
  const badge = document.getElementById("pendingValidationBadge");
  if (badge) {
    badge.textContent = pendingCount;
    badge.style.display = pendingCount > 0 ? "inline-block" : "none";
  }

  const tableBody = document.getElementById("pendingIntakesTableBody");
  if (!tableBody) return;

  const statusFilter = document.getElementById("pendingStatusFilter")?.value || "PENDIENTE_VALIDACION";

  const filtered = appState.pendingIntakes.filter(i => {
    if (statusFilter === "ALL") return true;
    return i.status === statusFilter;
  });

  const isAdmin = (appState.currentUser.role === 'ADMINISTRADOR');

  if (filtered.length === 0) {
    tableBody.innerHTML = `
      <tr>
        <td colspan="9" style="text-align: center; color: var(--text-muted); padding: 1.5rem;">
          No hay solicitudes de ingreso de inventario registradas en este filtro.
        </td>
      </tr>
    `;
    return;
  }

  tableBody.innerHTML = filtered.map(i => {
    const statusBadge = i.status === 'PENDIENTE_VALIDACION' 
      ? '<span class="badge badge-amber">⏳ Pendiente Validación</span>'
      : i.status === 'APROBADO'
      ? '<span class="badge badge-green">🟢 Aprobado (Ingresado)</span>'
      : '<span class="badge badge-red">🔴 Rechazado / Anulado</span>';

    const serialsLabel = (i.proposedSerials && i.proposedSerials.length > 0)
      ? `<div style="font-family: monospace; font-size: 0.75rem; color: var(--accent-green);">${i.proposedSerials.length} seriales</div>`
      : '<span style="color: var(--text-muted); font-size: 0.75rem;">N/A (Lote/Cantidad)</span>';

    return `
      <tr>
        <td style="font-size: 0.8rem;">${i.submittedAt}</td>
        <td><strong>👤 ${i.submittedBy}</strong></td>
        <td>
          <strong style="color: var(--accent-green);">${i.sku}</strong>
          <div style="font-size: 0.75rem; color: var(--text-muted);">${i.productName}</div>
        </td>
        <td>📍 ${i.locationName}</td>
        <td><strong style="font-size: 1.05rem; color: var(--accent-teal);">${i.proposedQuantity} Unds</strong></td>
        <td>${serialsLabel}</td>
        <td>${i.invoiceNumber || '-'}</td>
        <td>${statusBadge}</td>
        <td>
          ${i.status === 'PENDIENTE_VALIDACION' ? `
            ${isAdmin ? `
              <div style="display: flex; gap: 0.3rem; flex-wrap: wrap;">
                <button class="btn btn-secondary" style="padding: 0.2rem 0.45rem; font-size: 0.73rem;" onclick="openEditPendingIntakeModal('${i.id}')" title="Editar borrador sin generar movimientos ni salidas">
                  ✏️ Editar Borrador
                </button>
                <button class="btn btn-primary" style="padding: 0.2rem 0.45rem; font-size: 0.73rem; background: #10b981; border-color: #10b981;" onclick="approvePendingIntake('${i.id}')" title="Aprobar e ingresar existencias físicas al sistema">
                  ✅ Aprobar
                </button>
                <button class="btn btn-danger" style="padding: 0.2rem 0.45rem; font-size: 0.73rem;" onclick="rejectPendingIntake('${i.id}')" title="Anular propuesta de ingreso">
                  ❌ Rechazar
                </button>
              </div>
            ` : `
              <span style="font-size: 0.75rem; color: var(--text-muted);">⏳ Esperando revisión de Administrador</span>
            `}
          ` : `
            <span style="font-size: 0.75rem; color: var(--text-muted);">Sin acciones (Registro finalizado)</span>
          `}
        </td>
      </tr>
    `;
  }).join('');
}

function openEditPendingIntakeModal(intakeId) {
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo un Administrador puede editar borradores de ingreso.");
    return;
  }

  const intake = appState.pendingIntakes.find(i => i.id === intakeId);
  if (!intake || intake.status !== 'PENDIENTE_VALIDACION') return;

  const modal = document.getElementById("editPendingIntakeModal");
  if (!modal) return;

  document.getElementById("pendingIntakeEditId").value = intake.id;
  document.getElementById("pendingIntakeProductDisplay").value = `${intake.sku} - ${intake.productName}`;

  const locSelect = document.getElementById("pendingIntakeLocation");
  if (locSelect) {
    locSelect.innerHTML = appState.locations.filter(l => l.active).map(l => 
      `<option value="${l.id}" ${l.id === intake.locationId ? 'selected' : ''}>${l.name}</option>`
    ).join('');
  }

  document.getElementById("pendingIntakeQuantity").value = intake.proposedQuantity;
  document.getElementById("pendingIntakeInvoice").value = intake.invoiceNumber || "";
  document.getElementById("pendingIntakeNotes").value = intake.notes || "";

  const serialsGroup = document.getElementById("pendingIntakeSerialsGroup");
  const serialsText = document.getElementById("pendingIntakeSerialsText");
  if (intake.requiresSerial) {
    if (serialsGroup) serialsGroup.style.display = "block";
    if (serialsText) serialsText.value = (intake.proposedSerials || []).join(", ");
  } else {
    if (serialsGroup) serialsGroup.style.display = "none";
  }

  modal.classList.add("active");
}

function closeEditPendingIntakeModal() {
  const modal = document.getElementById("editPendingIntakeModal");
  if (modal) modal.classList.remove("active");
}

function handleSavePendingIntakeDraft(e) {
  e.preventDefault();
  const editId = document.getElementById("pendingIntakeEditId").value;
  const intake = appState.pendingIntakes.find(i => i.id === editId);
  if (!intake) return;

  const newLocId = document.getElementById("pendingIntakeLocation").value;
  const targetLoc = appState.locations.find(l => l.id === newLocId);
  const newQty = parseInt(document.getElementById("pendingIntakeQuantity").value);
  const newInvoice = document.getElementById("pendingIntakeInvoice").value.trim();
  const newNotes = document.getElementById("pendingIntakeNotes").value.trim();

  let newSerials = [];
  if (intake.requiresSerial) {
    const rawSerials = document.getElementById("pendingIntakeSerialsText")?.value || "";
    newSerials = rawSerials.split(',').map(s => s.trim()).filter(Boolean);
  }

  intake.locationId = newLocId;
  intake.locationName = targetLoc ? targetLoc.name : "Bodega Principal";
  intake.proposedQuantity = newQty;
  intake.invoiceNumber = newInvoice;
  intake.notes = newNotes;
  intake.proposedSerials = newSerials;

  savePendingIntakesToDisk();
  addActivityLog("MODIFICACION", "PendingIntakeDraft", `Administrador modificó borrador de ingreso '${intake.sku}' (Nueva cant: ${newQty}). Sin movimientos de salida.`);

  alert(`✅ BORRADOR ACTUALIZADO: La propuesta de ingreso fue modificada con éxito. Permanece en borrador hasta que haga clic en 'Aprobar'.`);
  closeEditPendingIntakeModal();
  renderPendingValidationsView();
}

function approvePendingIntake(intakeId) {
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo el Administrador está autorizado para aprobar e ingresar inventario.");
    return;
  }

  const intake = appState.pendingIntakes.find(i => i.id === intakeId);
  if (!intake || intake.status !== 'PENDIENTE_VALIDACION') return;

  const product = appState.products.find(p => p.id === intake.productId);
  if (!product) {
    alert("⚠️ ERROR: El producto asociado ya no existe en el catálogo.");
    return;
  }

  if (confirm(`¿Confirma la aprobación del ingreso de ${intake.proposedQuantity} unidades de '${product.sku}' a la sede '${intake.locationName}'?`)) {
    ensureProductLocations();

    product.physicalStock += intake.proposedQuantity;
    product.stockByLocation[intake.locationId] = (product.stockByLocation[intake.locationId] || 0) + intake.proposedQuantity;

    if (product.requiresSerial && intake.proposedSerials && intake.proposedSerials.length > 0) {
      intake.proposedSerials.forEach(sNum => {
        let serialItem = appState.serializedItems.find(i => i.serialNumber === sNum);
        if (!serialItem) {
          serialItem = {
            id: `ser-${Date.now()}-${Math.floor(Math.random()*1000)}`,
            productId: product.id,
            serialNumber: sNum,
            status: "EN_STOCK",
            currentLocationId: intake.locationId,
            currentCustomerId: null,
            entryDate: new Date().toISOString().substring(0, 10),
            saleDate: null,
            invoiceNumber: intake.invoiceNumber,
            attachments: [],
            history: [{
              type: "INGRESO_COMPRA",
              date: new Date().toISOString().substring(0, 10),
              user: appState.currentUser.name,
              description: `Ingreso de inventario aprobado por Administrador en sede '${intake.locationName}'`
            }]
          };
          appState.serializedItems.push(serialItem);
        } else {
          serialItem.status = "EN_STOCK";
          serialItem.currentLocationId = intake.locationId;
        }
      });
    }

    const committedMov = {
      id: `mov-app-${Date.now()}`,
      date: new Date().toISOString().substring(0, 10),
      type: "INGRESO_COMPRA",
      productId: product.id,
      quantity: intake.proposedQuantity,
      invoiceNumber: intake.invoiceNumber || `FAC-IN-${Date.now().toString().slice(-4)}`,
      customerName: "Ingreso Proveedor (Aprobado)",
      user: `${appState.currentUser.name} (Aprueba: ${intake.submittedBy})`,
      notes: `Aprobación de ingreso registrado originalmente por Logística. ${intake.notes || ''}`
    };

    appState.movements.unshift(committedMov);

    intake.status = "APROBADO";
    savePendingIntakesToDisk();

    addActivityLog("APROBACION", "InventoryIntake", `Administrador aprobó e ingresó ${intake.proposedQuantity} unidades de '${product.sku}' en sede '${intake.locationName}'.`);

    alert(`✅ INGRESO APROBADO EXITOSAMENTE: Se han adicionado ${intake.proposedQuantity} unidades al inventario físico de '${product.sku}'.`);
    renderAllViews();
  }
}

function rejectPendingIntake(intakeId) {
  if (!isAdminUser(appState.currentUser)) {
    alert("🔒 Restricción RBAC: Solo el Administrador está autorizado para rechazar propuestas de ingreso.");
    return;
  }

  const intake = appState.pendingIntakes.find(i => i.id === intakeId);
  if (!intake || intake.status !== 'PENDIENTE_VALIDACION') return;

  if (confirm(`¿Está seguro de rechazar y anular esta propuesta de ingreso de ${intake.proposedQuantity} unidades de '${intake.sku}'?`)) {
    intake.status = "RECHAZADO";
    savePendingIntakesToDisk();
    addActivityLog("RECHAZO", "InventoryIntake", `Administrador rechazó propuesta de ingreso de '${intake.sku}' de usuario '${intake.submittedBy}'.`);
    alert(`🔴 PROPUESTA RECHAZADA: El ingreso fue anulado y no afectará el inventario.`);
    renderAllViews();
  }
}

// ==========================================================================
// UNIVERSAL CAMERA SCANNER (BARCODES 1D, QR CODES, 2D DATAMATRIX, CODE 128)
// ==========================================================================

let currentCameraStream = null;
let cameraScannerInterval = null;

async function startCameraScanner(onCodeScanned) {
  const modal = document.getElementById("cameraScannerModal");
  const video = document.getElementById("cameraScannerVideo");
  const status = document.getElementById("cameraScannerStatus");
  if (!modal || !video) return;

  modal.classList.add("active");
  if (status) status.textContent = "Buscando cámara...";

  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: "environment" }
    });
    currentCameraStream = stream;
    video.srcObject = stream;
    await video.play();

    if (status) status.textContent = "📷 Cámara activa. Apunte al código de barras, QR o DataMatrix...";

    if ('BarcodeDetector' in window) {
      const barcodeDetector = new BarcodeDetector({
        formats: ['qr_code', 'code_128', 'code_39', 'ean_13', 'ean_8', 'upc_a', 'data_matrix', 'pdf417', 'aztec']
      });

      cameraScannerInterval = setInterval(async () => {
        try {
          const barcodes = await barcodeDetector.detect(video);
          if (barcodes.length > 0) {
            const scannedCode = barcodes[0].rawValue;
            if (navigator.vibrate) navigator.vibrate(120);
            closeCameraScannerModal();
            if (typeof onCodeScanned === 'function') {
              onCodeScanned(scannedCode);
            }
          }
        } catch (err) {}
      }, 250);
    } else {
      if (status) status.textContent = "💡 Digite o escanee con lector óptico USB/Bluetooth, o utilice Chrome/Safari en dispositivo móvil.";
    }
  } catch (err) {
    if (status) status.textContent = "❌ No se pudo acceder a la cámara. Verifique los permisos en su navegador.";
  }
}

function closeCameraScannerModal() {
  const modal = document.getElementById("cameraScannerModal");
  if (modal) modal.classList.remove("active");

  if (cameraScannerInterval) {
    clearInterval(cameraScannerInterval);
    cameraScannerInterval = null;
  }
  if (currentCameraStream) {
    currentCameraStream.getTracks().forEach(track => track.stop());
    currentCameraStream = null;
  }
}

// SERIAL INSPECTOR REGISTRATION CONTROLLER
function submitRegisterProductSerial(productId) {
  const input = document.getElementById("regSerialInput");
  const locSelect = document.getElementById("regSerialLocSelect");
  if (!input || !input.value.trim()) {
    alert("⚠️ Por favor ingrese o escanee un número de serie válido.");
    return;
  }

  const serialNum = input.value.trim().toUpperCase();
  const locId = locSelect ? locSelect.value : "loc-1";

  const exists = appState.serializedItems.some(i => i.serialNumber === serialNum);
  if (exists) {
    alert(`⚠️ El número de serie '${serialNum}' ya se encuentra registrado en el sistema.`);
    return;
  }

  const newSerialObj = {
    id: `ser-${Date.now()}-${Math.floor(Math.random()*1000)}`,
    productId: productId,
    serialNumber: serialNum,
    status: "EN_STOCK",
    currentLocationId: locId,
    currentCustomerId: null,
    entryDate: new Date().toISOString().split("T")[0],
    saleDate: null,
    invoiceNumber: null,
    attachments: [],
    history: [
      {
        type: "INGRESO_MANUAL",
        date: new Date().toISOString().split("T")[0],
        user: (appState.currentUser ? appState.currentUser.name : null) || "Administrador",
        description: "Registro de serial individual asignado a inventario de bodega.",
        attachments: []
      }
    ]
  };

  appState.serializedItems.push(newSerialObj);
  addActivityLog("CREACION", "SerialInspector", `Serial '${serialNum}' asignado a producto ID '${productId}'`);
  alert(`✅ Serial '${serialNum}' registrado y asignado exitosamente.`);

  openSerialInspectorModal(productId);
  renderCatalog();
}

function scanSerialForProductRegistration(productId) {
  startCameraScanner((code) => {
    const input = document.getElementById("regSerialInput");
    if (input) {
      input.value = code;
      submitRegisterProductSerial(productId);
    }
  });
}

function scanAndCheckTransferSerial() {
  startCameraScanner((code) => {
    const checkboxes = document.querySelectorAll(".transfer-serial-checkbox");
    let found = false;
    checkboxes.forEach(chk => {
      if (chk.value.toUpperCase() === code.toUpperCase()) {
        chk.checked = true;
        found = true;
      }
    });

    if (found) {
      alert(`✅ Serial '${code}' escaneado y marcado para traslado.`);
    } else {
      alert(`⚠️ El serial '${code}' no se encuentra disponible en la sede de origen seleccionada.`);
    }
  });
}

// Enforce default requiresSerial = false for all catalog products on load
if (appState && Array.isArray(appState.products)) {
  appState.products.forEach(p => {
    p.requiresSerial = false;
  });
}
